function.arguments:
{"command": "cd /workspace && python3 - <<'EOF'
import subprocess, string, collections, itertools
cmds = ['completion','delete','env','exec','export','find','help','history','import','list','list-services','read','tag','version','write']
def ld(s,t):
    if len(s)<len(t): s,t=t,s
    prev=list(range(len(t)+1))
    for i,c in enumerate(s):
        cur=[i+1]
        for j,d in enumerate(t):
            cur.append(min(prev[j+1]+1, cur[j]+1, prev[j]+(c!=d)))
        prev=cur
    return prev[-1]
cands=set()
for c in cmds:
    for k in range(1,len(c)+1):
        cands.add(c[:k])
for s in itertools.product(string.ascii_lowercase, repeat=3):
    cands.add(''.join(s))
def matches(q):
    m=[]
    for c in cmds:
        if ld(q,c)<=2 or c.startswith(q): m.append(c)
    return m
useful=[q for q in cands if len(matches(q))>=2]
print(len(useful))
pairs=set()
for q in useful:
    p=subprocess.run(['./executable',q],capture_output=True,text=True,timeout=30)
    out=p.stderr
    if 'Did you mean this?' in out:
        seg=out.split('Did you mean this?\n')[1].split('\n\n')[0]
        lst=[l.strip() for l in seg.split('\n')]
        for a,b in zip(lst,lst[1:]): pairs.add((a,b))
print(sorted(pairs))
deps=collections.defaultdict(set)
for a,b in pairs: deps[b].add(a)
order=[]; remaining=set(cmds)
while remaining:
    ready=sorted(x for x in remaining if not (deps[x]-set(order)))
    if not ready: print("CYCLE",remaining); break
    order.append(ready[0]); remaining.discard(ready[0])
print(order)
EOF"}

