{"command": "cd /workspace && cat > cmd/root.go <<'EOF'
package cmd

import (
	"fmt"
	"os"
	"strings"

	"chamber/store"

	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

var (
	chamberVersion    = "dev"
	chamberCommit     = "none"
	chamberDate       = "unknown"
	logDebug  = false
)

// globalOptions holds values of global (persistent) flags
type globalOptions struct {
	Backend        string
	BackendS3Bucket string
	KMSKeyAlias    string
	Retries        int
	RetryMode      string
	Verbose        bool
}

var globalOpts = &globalOptions{}

func init() {
	rootCmd.PersistentFlags().StringVarP(&globalOpts.Backend, "backend", "b", "ssm",
		"Backend to use; AKA $CHAMBER_SECRET_BACKEND\n"+
			"\tnull: no-op\n"+
			"\tssm: SSM Parameter Store\n"+
			"\tsecretsmanager: Secrets Manager\n"+
			"\ts3: S3; requires --backend-s3-bucket\n"+
			"\ts3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys).")
	rootCmd.PersistentFlags().StringVar(&globalOpts.BackendS3Bucket, "backend-s3-bucket", "",
		"bucket for S3 backend; AKA $CHAMBER_S3_BUCKET")
	rootCmd.PersistentFlags().StringVar(&globalOpts.KMSKeyAlias, "kms-key-alias", "alias/parameter_store_key",
		"KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend.")
	rootCmd.PersistentFlags().IntVarP(&globalOpts.Retries, "retries", "r", 10,
		"For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES")
	rootCmd.PersistentFlags().StringVar(&globalOpts.RetryMode, "retry-mode", "standard",
		"For SSM, the model used to retry requests\n"+
			"  standard\n"+
			"  adaptive")
	rootCmd.PersistentFlags().BoolVar(&globalOpts.Verbose, "verbose", false,
		"Print more information to STDERR")

	// env fallbacks
	initFromEnv(rootCmd.PersistentFlags())

	rootCmd.AddCommand(readCmd)
	rootCmd.AddCommand(listCmd)
	rootCmd.AddCommand(writeCmd)
	rootCmd.AddCommand(envCmd)
	rootCmd.AddCommand(listServicesCmd)
	rootCmd.AddCommand(deleteCmd)
	rootCmd.AddCommand(historyCmd)
	rootCmd.AddCommand(exportCmd)
	rootCmd.AddCommand(findCmd)
	rootCmd.AddCommand(importCmd)
	rootCmd.AddCommand(execCmd)
	rootCmd.AddCommand(tagCmd)
	rootCmd.AddCommand(versionCmd)
}

func initFromEnv(flags *pflag.FlagSet) {
	// Flags take precedence over environment variables
	setIfUnset := func(name, env string) {
		if v, ok := os.LookupEnv(env); ok {
			if !flags.Changed(name) {
				_ = flags.Set(name, v)
			}
		}
	}
	setIfUnset("backend", "CHAMBER_SECRET_BACKEND")
	setIfUnset("backend-s3-bucket", "CHAMBER_S3_BUCKET")
	setIfUnset("kms-key-alias", "CHAMBER_KMS_KEY_ALIAS")
	if v, ok := os.LookupEnv("CHAMBER_RETRIES"); ok {
		if !flags.Changed("retries") {
			_ = flags.Set("retries", v)
		}
	}
}

var rootCmd = &cobra.Command{
	Use:           "chamber",
	Short:         "CLI for storing secrets",
	Long:          "CLI for storing secrets",
	SilenceUsage:  true,
}

// Execute runs the root command
func Execute() {
	configureLogging()
	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func configureLogging() {
	if globalOpts.Verbose {
		logDebug = true
	}
}

// secretStore returns the store for the given backend
func secretStore() (store.Store, error) {
	backend := globalOpts.Backend
	switch strings.ToUpper(backend) {
	case "NULL":
		return store.NewNullStore(), nil
	case "SSM":
		return store.NewSSMStore(globalOpts.Retries, globalOpts.RetryMode)
	case "SECRETMANAGER":
		return store.NewSecretsManagerStore(globalOpts.Retries, globalOpts.RetryMode)
	case "S3", "S3-KMS":
		if globalOpts.BackendS3Bucket == "" {
			return nil, fmt.Errorf("Must set bucket for s3 backend")
		}
		return store.NewS3Store(globalOpts.BackendS3Bucket, globalOpts.KMSKeyAlias, globalOpts.Retries, strings.ToUpper(backend) == "S3-KMS")
	default:
		return nil, fmt.Errorf("invalid backend `%s`", strings.ToUpper(backend))
	}
}
EOF
echo ok"}

