	WriteTags(key types.ParameterRequest, tags []types.Tag, deleteOthers bool) error
	ReadTags(key types.ParameterRequest) ([]types.Tag, error)
	DeleteTags(key types.ParameterRequest, tags []types.Tag) error
	Delete(parameters ...types.ParameterRequest) error
}

// ErrParameterNotFound is returned when a secret is not in the store
var ErrParameterNotFound = fmt.Errorf("secret not found")

var validServiceRegexp = regexp.MustCompile(`^[a-zA-Z0-9_.\-]+$`)
var validLabelledServiceRegexp = regexp.MustCompile(`^[a-zA-Z0-9_.\-]+(/[a-zA-Z0-9_.\-]+)*(:[a-zA-Z0-9_.\-]+)+$`)
var validServicePathRegexp = regexp.MustCompile(`^[a-zA-Z0-9_.\-]+(/[a-zA-Z0-9_.\-]+)*$`)
var validKeyRegexp = regexp.MustCompile(`^[a-zA-Z0-9_.\-]+$`)

// validateServiceName validates a service name, allowing labels (service:label)
// which is used by commands that can reference labelled services
func validateServiceName(service string, withLabels bool) error {
	normalized := strings.ToLower(service)
	ok := validServicePathRegexp.MatchString(normalized)
	if !ok && withLabels {
		ok = validLabelledServiceRegexp.MatchString(normalized)
	}
	if !ok {
		if withLabels {
			return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names, and colon followed by a label name. Service names must not start or end with a forward slash or colon", normalized)
		}
		return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names. Service names must not start or end with a forward slash", normalized)
	}
	return nil
}

// validateKeyName validates a key name
func validateKeyName(key string, exact bool) error {
	normalized := key
	if !exact {
		normalized = strings.ToLower(key)
	}
	if !validKeyRegexp.MatchString(normalized) {
		return fmt.Errorf("Failed to validate key name '%s'. Only alphanumeric, dashes, full stops and underscores are allowed for key names", normalized)
	}
	return nil
}

// ValidateService validates a service name and wraps errors
func ValidateService(service string, withLabels bool) error {
	if err := validateServiceName(service, withLabels); err != nil {
		return fmt.Errorf("Failed to validate service: %s", err)
	}
	return nil
}

// ValidateKey validates a key name and wraps errors
func ValidateKey(key string, exact bool) error {
	if err := validateKeyName(key, exact); err != nil {
		return fmt.Errorf("Failed to validate key: %s", err)
	}
	return nil
}

// Store wraps a backend and provides validation
type Store struct {
	backend Backend
}

// New creates a store wrapping the given backend
func New(backend Backend) *Store {
	return &Store{backend: backend}
}

func (s *Store) validateService(service string, withLabels bool) error {
	return ValidateService(service, withLabels)
}

func (s *Store) validateKey(key string, exact bool) error {
	return ValidateKey(key, exact)
}

// ListServices lists all services
func (s *Store) ListServices(providers ...string) ([]types.Service, error) {
	return s.backend.ListServices(providers...)
}

// List lists all the secrets for a service
func (s *Store) List(paths ...string) ([]types.Parameter, error) {
	return s.backend.List(paths...)
}

// Get reads secrets from the store
func (s *Store) Get(parameters ...types.ParameterRequest) ([]types.ParameterVersion, error) {
	return s.backend.Get(parameters...)
}

// GetHistory reads the history of secrets from the store
func (s *Store) GetHistory(parameters ...types.ParameterRequest) ([]types.ParameterVersionHistory, error) {
	return s.backend.GetHistory(parameters...)
}

// Write writes secrets to the store
func (s *Store) Write(parameters ...types.Parameter) error {
	return s.backend.Write(parameters...)
}

// WriteWithTags writes a secret with tags
func (s *Store) WriteWithTags(parameter types.Parameter, tags []types.Tag) error {
	return s.backend.WriteWithTags(parameter, tags)
}

// WriteTags writes tags for a secret
func (s *Store) WriteTags(key types.ParameterRequest, tags []types.Tag, deleteOthers bool) error {
	return s.backend.WriteTags(key, tags, deleteOthers)
}

// ReadTags reads tags for a secret
func (s *Store) ReadTags(key types.ParameterRequest) ([]types.Tag, error) {
	return s.backend.ReadTags(key)
}

// DeleteTags deletes tags for a secret
func (s *Store) DeleteTags(key types.ParameterRequest, tags []types.Tag) error {
	return s.backend.DeleteTags(key, tags)
}

// Delete deletes secrets from the store
func (s *Store) Delete(parameters ...types.ParameterRequest) error {
	return s.backend.Delete(parameters...)
}

// sortParametersByModified sorts parameters by their modification time
func sortParametersByModified(parameters []types.Parameter) {
	for i := 1; i < len(parameters); i++ {
		for j := i; j > 0 && parameters[j].Modified.After(parameters[j-1].Modified); j-- {
			parameters[j], parameters[j-1] = parameters[j-1], parameters[j]
		}
	}
}

var _ = time.Now
