	"fmt"
	"os"
	"text/tabwriter"

	"chamber/store"
	"chamber/types"

	"github.com/spf13/cobra"
)

var historyCmd = &cobra.Command{
	Use:   "history <service> <key>",
	Short: "View the history of a secret",
	Args:  exactArgs(2),
	RunE: func(cmd *cobra.Command, args []string) error {
		cmd.SilenceUsage = true

		service, key := args[0], args[1]

		if err := store.ValidateService(service, false); err != nil {
			return err
		}
		if err := store.ValidateKey(key, false); err != nil {
			return err
		}

		ss, err := secretStore()
		if err != nil {
			return fmt.Errorf("Failed to get secret store: %s", err)
		}

		parameterRequest := types.ParameterRequest{Service: service, Key: key, Version: -1}

		history, err := ss.GetHistory(parameterRequest)
		if err != nil {
			return fmt.Errorf("Failed to get history: %s", err)
		}

		tw := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
		fmt.Fprintln(tw, "Event\tVersion\tDate\tUser")
		for _, version := range history {
			event := "Create"
			switch version.Version {
			case 1:
				event = "Create"
			default:
				event = "Update"
			}
			fmt.Fprintf(tw, "%s\t%d\t%s\t%s\n", event, version.Version,
				version.Modified.Local().Format(timeFormat), version.User)
		}
		return tw.Flush()
	},
}
EOF
echo ok"}

