package cmd

import (
	"fmt"
	"io"
	"os"
	"strings"

	"chamber/store"
	"chamber/types"

	"github.com/spf13/cobra"
)

var writeOpts struct {
	Singleline    bool
	SkipUnchanged bool
	Tags          map[string]string
}

var writeCmd = &cobra.Command{
	Use:   "write <service> <key> [--] <value|->",
	Short: "write a secret",
	Args:  exactArgs(3),
	RunE: func(cmd *cobra.Command, args []string) error {
		cmd.SilenceUsage = true

		service, key, value := args[0], args[1], args[2]

		if err := store.ValidateService(service, false); err != nil {
			return err
		}
		if err := store.ValidateKey(key, false); err != nil {
			return err
		}

		if value == "-" {
			b, err := io.ReadAll(os.Stdin)
			if err != nil {
				return fmt.Errorf("Failed to read stdin: %s", err)
			}
			value = string(b)
		}

		if writeOpts.Singleline {
			if !strings.HasSuffix(value, "\n") {
				value += "\n"
			}
		}

		ss, err := secretStore()
		if err != nil {
			return fmt.Errorf("Failed to get secret store: %s", err)
		}

		parameter := types.Parameter{
			Key:   key,
			Value: value,
		}

		if cmd.Flags().Changed("tags") {
			tags := make([]types.Tag, 0, len(writeOpts.Tags))
			for k, v := range writeOpts.Tags {
				tags = append(tags, types.Tag{Key: k, Value: v})
			}
			sortTags(tags)
			return ss.WriteWithTags(parameter, tags)
		}

		return ss.Write(parameter)
	},
}

func sortTags(tags []types.Tag) {
	for i := 1; i < len(tags); i++ {
		for j := i; j > 0 && tags[j].Key < tags[j-1].Key; j-- {
			tags[j], tags[j-1] = tags[j-1], tags[j]
		}
	}
}
EOF
