package cmd

import (
	"fmt"
	"io"
	"os"

	"chamber/importer"
	"chamber/store"
	"chamber/types"

	"github.com/spf13/cobra"
)

var importOpts struct {
	NormalizeKeys bool
}

var importCmd = &cobra.Command{
	Use:   "import <service> <file|->",
	Short: "import secrets from json or yaml",
	Args:  exactArgs(2),
	RunE: func(cmd *cobra.Command, args []string) error {
		cmd.SilenceUsage = true

		service, file := args[0], args[1]

		if err := store.ValidateService(service, false); err != nil {
			return err
		}

		ss, err := secretStore()
		if err != nil {
			return fmt.Errorf("Failed to get secret store: %s", err)
		}

		var input io.Reader
		if file == "-" {
			input = os.Stdin
		} else {
			f, err := os.Open(file)
			if err != nil {
				return fmt.Errorf("Failed to open file: %s", err)
			}
			defer f.Close()
			input = f
		}

		secrets, err := importer.DecodeSecrets(input)
		if err != nil {
			return fmt.Errorf("Failed to decode input as json: %s", err)
		}

		count := 0
		for _, secret := range secrets {
			key := secret.Key
			if importOpts.NormalizeKeys {
				key = importer.NormalizeKey(key)
			}
			if err := ss.Write(types.Parameter{Key: key, Value: secret.Value}); err != nil {
				return fmt.Errorf("Failed to write secret: %s", err)
			}
			count++
		}

		fmt.Fprintf(os.Stdout, "Successfully imported %d secrets\n", count)
		return nil
	},
}
EOF
cat > importer/importer.go <<'EOF'
package importer

import (
	"io"
	"strings"

	"chamber/yaml"
)

// Secret is a key/value pair from an import source
type Secret struct {
	Key   string
	Value string
}

// DecodeSecrets reads a json or yaml document and returns the secrets
func DecodeSecrets(input io.Reader) ([]Secret, error) {
	data, err := io.ReadAll(input)
	if err != nil {
		return nil, err
	}
	m, err := yaml.UnmarshalMap(data)
	if err != nil {
		return nil, err
	}
	secrets := make([]Secret, 0, len(m))
	for k, v := range m {
		secrets = append(secrets, Secret{Key: k, Value: v})
	}
	sortSecrets(secrets)
	return secrets, nil
}

// NormalizeKey normalizes a key the same way chamber write does
func NormalizeKey(key string) string {
	return strings.ToLower(key)
}

func sortSecrets(secrets []Secret) {
	for i := 1; i < len(secrets); i++ {
		for j := i; j > 0 && secrets[j].Key < secrets[j-1].Key; j-- {
			secrets[j], secrets[j-1] = secrets[j-1], secrets[j]
		}
	}
}
EOF
echo ok"}

