	Short: "Write tags for a specific secret",
	Args:  cobra.MinimumNArgs(3),
	RunE: func(cmd *cobra.Command, args []string) error {
		cmd.SilenceUsage = true

		service, key := args[0], args[1]

		if err := store.ValidateService(service, false); err != nil {
			return err
		}
		if err := store.ValidateKey(key, false); err != nil {
			return err
		}

		tags, err := parseTags(args[2:])
		if err != nil {
			return err
		}

		ss, err := secretStore()
		if err != nil {
			return fmt.Errorf("Failed to get secret store: %s", err)
		}

		if err := ss.WriteTags(types.ParameterRequest{Service: service, Key: key, Version: -1}, tags, tagWriteOpts.DeleteOtherTags); err != nil {
			return fmt.Errorf("Failed to write tags: %s", err)
		}
		return nil
	},
}

var tagDeleteCmd = &cobra.Command{
	Use:   "delete <service> <key> <tag key>...",
	Short: "Delete tags for a specific secret",
	Args:  cobra.MinimumNArgs(3),
	RunE: func(cmd *cobra.Command, args []string) error {
		cmd.SilenceUsage = true

		service, key := args[0], args[1]

		if err := store.ValidateService(service, false); err != nil {
			return err
		}
		if err := store.ValidateKey(key, false); err != nil {
			return err
		}

