		if err != nil {
			return fmt.Errorf("Failed to get secret store: %s", err)
		}

		tags := make([]types.Tag, 0, len(args)-2)
		for _, name := range args[2:] {
			tags = append(tags, types.Tag{Key: name})
		}

		if err := ss.DeleteTags(types.ParameterRequest{Service: service, Key: key, Version: -1}, tags); err != nil {
			return fmt.Errorf("Failed to delete tags: %s", err)
