package yaml

// Position is a 1-based line/column position in a document
type Position struct {
	Line int
	Col  int
}

// source holds the document lines for rendering error snippets
type source struct {
	lines []string
}

func newSource(data []byte) *source {
	text := string(data)
	text = strings.ReplaceAll(text, "\r\n", "\n")
	lines := strings.Split(text, "\n")
	return &source{lines: lines}
}

func (s *source) lineCount() int { return len(s.lines) }

func (s *source) line(i int) string {
	if i < 1 || i > len(s.lines) {
		return ""
	}
	return s.lines[i-1]
}

func (s *source) width(start, end int) int {
	w := 0
	for i := start; i <= end; i++ {
		l := fmt.Sprintf("%d", i)
		if len(l) > w {
			w = len(l)
		}
	}
	if w < 2 {
		w = 2
	}
	return w
}

// snippet renders the error snippet for the given position
func (s *source) snippet(pos Position, caretLine int) string {
	n := len(s.lines)
	start := pos.Line - 3
	if start < 1 {
		start = 1
	}
	end := pos.Line + 3
	if end > n {
		end = n
	}
	if caretLine-1 > end {
		end = caretLine - 1
		if end > n {
			end = n
		}
	}
	w := s.width(start, end)
	numFmt := fmt.Sprintf("%%%dd | ", w)

	var sb strings.Builder
	for i := start; i <= end; i++ {
		prefix := "  "
		if i == pos.Line {
			prefix = "> "
		}
		sb.WriteString(prefix)
		sb.WriteString(fmt.Sprintf(numFmt, i))
		sb.WriteString(s.line(i))
		sb.WriteString("\n")
		if i == pos.Line {
			sb.WriteString(strings.Repeat(" ", 2+w+3+pos.Col-1))
			sb.WriteString("^\n")
		}
	}
	// trailing line, rendered empty, when the document continues past the window
	if end < n {
		end++
		sb.WriteString("  ")
		sb.WriteString(fmt.Sprintf(numFmt, end))
	}
	return sb.String()
}
EOF
