package yaml

import (
	"strings"
	"unicode/utf8"
)

// scanner walks the document tracking line/column positions
type scanner struct {
	src  *source
	text string
	pos  int // rune index
	line int // 1-based
	col  int // 1-based
}

func newScanner(src *source) *scanner {
	return &scanner{src: src, text: strings.Join(src.lines, "\n"), line: 1, col: 1}
}

func (s *scanner) eof() bool {
	return s.pos >= len([]rune(s.text))
}

func (s *scanner) runes() []rune {
	if s.rs == nil {
		s.rs = []rune(s.text)
	}
	return s.rs
}

func (s *scanner) peek() rune {
	rs := s.runes()
	if s.pos >= len(rs) {
		return 0
	}
	return rs[s.pos]
}

func (s *scanner) peekAt(n int) rune {
	rs := s.runes()
	if s.pos+n >= len(rs) {
		return 0
	}
	return rs[s.pos+n]
}

func (s *scanner) next() rune {
	rs := s.runes()
	if s.pos >= len(rs) {
		return 0
	}
	r := rs[s.pos]
	s.pos++
	if r == '\n' {
		s.line++
		s.col = 1
	} else {
		s.col++
	}
	return r
}

func (s *scanner) position() Position {
	return Position{Line: s.line, Col: s.col}
}

// lineEnd returns the rune index of the end of the current line (exclusive of newline)
func (s *scanner) lineEnd() int {
	rs := s.runes()
	i := s.pos
	for i < len(rs) && rs[i] != '\n' {
		i++
	}
	return i
}

func (s *scanner) atLineEnd() bool {
	return s.eof() || s.peek() == '\n'
}

// skipSpaces skips spaces (not tabs) on the current line
func (s *scanner) skipSpaces() {
	for !s.eof() && (s.peek() == ' ' || s.peek() == '\t') {
		if s.peek() == '\t' {
			return
		}
		s.next()
	}
}

// indentOf returns the number of leading spaces on the current line and whether a tab was found
func (s *scanner) indentOf() (int, bool) {
	n := 0
	rs := s.runes()
	i := s.lineStart()
	tab := false
	for i < len(rs) {
		if rs[i] == ' ' {
			n++
		} else if rs[i] == '\t' {
			tab = true
		} else {
			break
		}
		i++
	}
	return n, tab
}

func (s *scanner) lineStart() int {
	rs := s.runes()
	i := s.pos
	for i > 0 && rs[i-1] != '\n' {
		i--
	}
	return i
}

// moveToLineStart moves the scanner to the first non-space character of the current line
func (s *scanner) moveToLineStart() {
	start := s.lineStart()
	for s.pos > start {
		s.pos--
	}
	s.col = 1
}

func (s *scanner) skipToNextLine() {
	for !s.eof() && s.peek() != '\n' {
		s.next()
	}
	if !s.eof() {
		s.next()
	}
}

// trailingComment reports whether the rest of the line is blank or a comment
func (s *scanner) restIsBlankOrComment() bool {
	i := s.lineEnd()
	rs := s.runes()
	j := s.pos
	for j < i {
		r := rs[j]
		if r == ' ' || r == '\t' {
			j++
			continue
		}
		if r == '#' {
			return true
		}
		return false
	}
	return true
}
EOF
echo ok"}

