package yaml

// node kinds
const (
	kindScalar = iota
	kindMapping
	kindSequence
	kindAlias
	kindTagged
)

// resolved scalar types
const (
	typeStr   = "string"
	typeInt   = "int"
	typeFloat = "float"
	typeBool  = "boolean"
	typeNull  = "null"
	typeInf   = "inf"
	typeNan   = "nan"
	typeSeq   = "sequence"
	typeMap   = "map"
	typeTag   = "tag"
)

type pair struct {
	key   *node
	value *node
}

type node struct {
	kind    int
	tag     string // resolved type for scalars
	value   string
	quoted  bool
	items   []*node
	pairs   []pair
	pos     Position
	endLine int
	anchor  string
	alias   string
	tagText string
}

// scalarType resolves a plain scalar to its yaml type
func scalarType(s string) string {
	if s == "" {
		return typeNull
	}
	switch s {
	case "null", "Null", "NULL", "~":
		return typeNull
	case "true", "True", "TRUE", "false", "False", "FALSE":
		return typeBool
	case ".inf", ".Inf", ".INF", "-.inf", "-.Inf", "-.INF", "+.inf":
		// only un-signed and negative forms are resolved
		if s == "+.inf" {
			return typeStr
		}
		return typeInf
	case ".nan", ".NaN", ".NAN":
		return typeNan
	}
	if isInt(s) {
		return typeInt
	}
	if isFloat(s) {
		return typeFloat
	}
	return typeStr
}

func isInt(s string) bool {
	t := strings.ReplaceAll(s, "_", "")
	if t == "" {
		return false
	}
	neg := false
	if t[0] == '+' || t[0] == '-' {
		neg = true
		t = t[1:]
	}
	if t == "" {
		return false
	}
	if len(t) > 2 && t[0] == '0' {
		switch t[1] {
		case 'x', 'X':
			return allDigits(t[2:], "0123456789abcdefABCDEF")
		case 'o', 'O':
			return allDigits(t[2:], "01234567")
		case 'b', 'B':
			return allDigits(t[2:], "01")
		}
	}
	if len(t) > 1 && t[0] == '0' && allDigits(t, "01234567") {
		return true
	}
	return allDigits(t, "0123456789")
}

func isFloat(s string) bool {
	t := strings.ReplaceAll(s, "_", "")
	if t == "" {
		return false
	}
	if t[0] == '+' || t[0] == '-' {
		t = t[1:]
	}
	if t == "" {
		return false
	}
	dot := false
	digits := false
	for i := 0; i < len(t); i++ {
