{"command": "cd /workspace && cat > yaml/parser.go <<'EOF'
package yaml

import (
	"io"
	"strings"
)

type parser struct {
	s       *scanner
	src     *source
	anchors map[string]*node
}

// UnmarshalMap parses the first yaml document in data as a map of strings
func UnmarshalMap(data []byte) (map[string]string, error) {
	src := newSource(data)
	p := &parser{s: newScanner(src), src: src, anchors: map[string]*node{}}
	root, err := p.parseDocument()
	if err != nil {
		return nil, err
	}
	return decodeMap(root, src)
}

func decodeMap(root *node, src *source) (map[string]string, error) {
	switch root.kind {
	case kindMapping:
	case kindSequence:
		return nil, syntaxErrf(src, root.pos, root.endLine+1, "%s was used where mapping is expected", typeSeq)
	case kindTagged:
		return nil, syntaxErrf(src, root.pos, root.endLine+1, "%s was used where mapping is expected", typeTag)
	case kindScalar:
		if root.tag == typeNull {
			return nil, eofErr()
		}
		return nil, syntaxErrf(src, root.pos, root.endLine+1, "%s was used where mapping is expected", root.tag)
	case kindAlias:
		return nil, syntaxErrf(src, root.pos, root.endLine+1, "%s was used where mapping is expected", typeStr)
	}
	out := make(map[string]string, len(root.pairs))
	positions := map[string]Position{}
	for _, kv := range root.pairs {
		if kv.value.kind != kindScalar {
			if err := checkScalarValue(kv.value, src); err != nil {
				return nil, err
			}
		}
		if kv.value.tag == typeNull && !kv.value.quoted {
			out[kv.key.value] = ""
			continue
		}
		if prev, ok := positions[kv.key.value]; ok {
			return nil, syntaxErrf(src, kv.key.pos, kv.key.endLine+1, "mapping key %q already defined at [%d:%d]", kv.key.value, prev.Line, prev.Col)
		}
		positions[kv.key.value] = kv.key.pos
		out[kv.key.value] = kv.value.value
	}
	return out, nil
}

func checkScalarValue(n *node, src *source) error {
	switch n.kind {
	case kindMapping:
		return syntaxErrf(src, n.pos, n.endLine+1, "cannot unmarshal map[string]interface {} into Go value of type string")
	case kindSequence:
		return syntaxErrf(src, n.pos, n.endLine+1, "cannot unmarshal []interface {} into Go value of type string")
	case kindAlias:
		return nil
	}
	return nil
}

// parseDocument parses the first document in the stream
func (p *parser) parseDocument() (*node, error) {
	p.skipBlanksAndComments()
	if p.s.eof() {
		return nil, eofErr()
	}
	// directives must be followed by a document start
	if p.s.peek() == '%' {
		pos := p.s.position()
		return nil, syntaxErrf(p.src, pos, pos.Line+1, "unexpected directive value. document not started")
	}
	// document start marker
	if p.isDocumentStart() {
		p.skipDocumentStart()
		p.skipBlanksAndComments()
		if p.s.eof() || p.isDocumentEnd() {
			return nil, eofErr()
		}
	}
	root, err := p.parseBlockNode(0, false)
	if err != nil {
		return nil, err
	}
	// after the document, any other content is an error
	if err := p.expectDocumentEnd(); err != nil {
		return nil, err
	}
	return root, nil
}

func (p *parser) expectDocumentEnd() error {
	for {
		if p.s.eof() {
			return nil
		}
		p.skipBlanksAndComments()
		if p.s.eof() {
			return nil
		}
		if p.isDocumentEnd() || p.isDocumentStart() {
			p.skipDocumentMarker()
			continue
		}
		pos := p.s.position()
		return syntaxErrf(p.src, pos, pos.Line+1, "value is not allowed in this context")
	}
}

func (p *parser) isDocumentStart() bool {
	if p.s.peek() != '-' {
		return false
	}
	return p.s.peekAt(1) == '-' && p.s.peekAt(2) == '-'
}

func (p *parser) isDocumentEnd() bool {
	if p.s.peek() != '.' {
		return false
	}
	return p.s.peekAt(1) == '.' && p.s.peekAt(2) == '.'
}

func (p *parser) skipDocumentStart() {
	p.consumeDocumentMarker()
}

func (p *parser) skipDocumentMarker() {
	p.consumeDocumentMarker()
	p.skipBlanksAndComments()
}

func (p *parser) consumeDocumentMarker() {
	for !p.s.eof() && p.s.peek() != '\n' {
		p.s.next()
	}
	if !p.s.eof() {
		p.s.next()
	}
	p.skipBlanksAndComments()
}

// skipBlanksAndComments skips empty lines and comment lines
func (p *parser) skipBlanksAndComments() {
	for !p.s.eof() {
		// move to the first non-space character of the current line
		p.s.moveToLineStart()
		start := p.s.lineStart()
		i := start
		rs := p.s.runes()
		for i < len(rs) && (rs[i] == ' ' || rs[i] == '\t') {
			i++
		}
		if i >= len(rs) {
			// blank line
			if p.s.eof() {
				return
			}
			p.s.skipToNextLine()
			continue
		}
		if rs[i] == '\n' {
			p.s.skipToNextLine()
			continue
		}
		if rs[i] == '#' {
			p.s.skipToNextLine()
			continue
		}
		// position the scanner at the first content character
		for p.s.pos < i {
			p.s.next()
		}
		return
	}
}

// parseBlockNode parses a node in block context
func (p *parser) parseBlockNode(minIndent int, inSeq bool) (*node, error) {
	p.skipBlanksAndComments()
	if p.s.eof() {
		return nil, eofErr()
	}
	if p.isDocumentEnd() || p.isDocumentStart() {
		return nil, eofErr()
	}
	indent, tab := p.s.indentOf()
	if tab {
		pos := p.s.position()
		return nil, syntaxErrf(p.src, pos, pos.Line+1, "found character '%c' that cannot start any token", '\t')
	}
	if indent < minIndent {
		return nil, nil
	}
	// properties (anchor/tag) may precede the node
	anchor, tag, err := p.parseProperties(indent)
	if err != nil {
		return nil, err
	}
	if p.s.eof() || p.s.atLineEnd() {
		if tag != "" || anchor != "" {
			return nil, syntaxErrf(p.src, Position{Line: indent0Line(p), Col: 1}, 0, "undefined anchor value")
		}
		return nil, nil
	}
	var n *node
	if p.s.peek() == '-' && isSeqEntry(p.s) {
		n, err = p.parseBlockSequence(indent)
	} else if hasKeyColon(p.s) {
		n, err = p.parseBlockMapping(indent)
	} else {
		n, err = p.parseScalar(indent)
	}
	if err != nil {
		return nil, err
	}
	if tag != "" {
		n = &node{kind: kindTagged, tagText: tag, tag: n.tag, value: n.value, pos: n.pos, endLine: n.endLine}
	}
	if anchor != "" {
		p.anchors[anchor] = n
		n.anchor = anchor
	}
	return n, nil
}

func indent0Line(p *parser) int {
	return p.s.line
}

func isSeqEntry(s *scanner) bool {
	n := s.peekAt(1)
	return n == ' ' || n == '\n' || n == 0 || n == '\t'
}
EOF
echo ok"}

{"command": "cd /workspace && cat > yaml/block.go <<'EOF'
package yaml

import (
	"strings"
)

// parseBlockSequence parses a block sequence at the given indentation
func (p *parser) parseBlockSequence(indent int) (*node, error) {
	seq := &node{kind: kindSequence, pos: p.s.position(), tag: typeSeq}
	for {
		if p.s.eof() {
			break
		}
		// the scanner is at the '-' of an entry
		entryPos := p.s.position()
		p.s.next() // consume '-'
		// skip spaces
		for !p.s.eof() && p.s.peek() == ' ' {
			p.s.next()
		}
		var item *node
		var err error
		if p.s.atLineEnd() || p.s.restIsBlankOrComment() {
			// item content on following lines
			p.s.skipToNextLine()
			item, err = p.parseBlockNode(indent + 1, true)
			if err != nil {
				return nil, err
			}
			if item == nil {
				item = p.nullNode(entryPos)
			}
		} else {
			item, err = p.parseBlockNode(indent, true)
			if err != nil {
				return nil, err
			}
			if item == nil {
				item = p.nullNode(entryPos)
			}
		}
		item.endLine = p.s.line
		if item.endLine < entryPos.Line {
			item.endLine = entryPos.Line
		}
		seq.items = append(seq.items, item)
		// next entry
		nl, err := p.nextContentLine()
		if err != nil {
			return nil, err
		}
		if nl == nil {
			break
		}
		if nl.indent < indent {
			break
		}
		if nl.indent > indent {
			return nil, syntaxErrf(p.src, item.pos, item.endLine+1, "unexpected key name")
		}
		if !nl.isSeq {
			return nil, syntaxErrf(p.src, nl.pos, nl.pos.Line+1, "value is not allowed in this context")
		}
	}
	seq.endLine = p.s.line
	return seq, nil
}

// contentLine describes the next line with content
type contentLine struct {
	indent int
	pos    Position
	isSeq  bool
	isMap  bool
}

// nextContentLine advances to the next line with content and describes it.
// Returns nil at end of input
func (p *parser) nextContentLine() (*contentLine, error) {
	p.skipBlanksAndComments()
	if p.s.eof() {
		return nil, nil
	}
	if p.isDocumentEnd() || p.isDocumentStart() {
		return nil, nil
	}
	indent, tab := p.s.indentOf()
	if tab {
		return nil, syntaxErrf(p.src, p.s.position(), p.s.line+1, "found character '%c' that cannot start any token", '\t')
	}
	cl := &contentLine{indent: indent, pos: p.s.position()}
	if p.s.peek() == '-' && isSeqEntry(p.s) {
		cl.isSeq = true
	} else if hasKeyColon(p.s) {
		cl.isMap = true
	}
	return cl, nil
}

// parseBlockMapping parses a block mapping at the given indentation
func (p *parser) parseBlockMapping(indent int) (*node, error) {
	m := &node{kind: kindMapping, pos: p.s.position(), tag: typeMap}
	keys := map[string]Position{}
	for {
		if p.s.eof() {
			break
		}
		keyPos := p.s.position()
		key, err := p.parseKey()
		if err != nil {
			return nil, err
		}
		if key == nil {
			return nil, syntaxErrf(p.src, keyPos, keyPos.Line+1, "unexpected key name")
		}
		// expect colon
		if p.s.peek() != ':' {
			pos := p.s.position()
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find expected ':'")
		}
		p.s.next()
		valPos := p.s.position()
		// skip spaces
		for !p.s.eof() && (p.s.peek() == ' ' || p.s.peek() == '\t') {
			p.s.next()
		}
		var value *node
		sameLine := false
		if p.s.atLineEnd() || p.s.restIsBlankOrComment() {
			p.s.skipToNextLine()
			cl, err := p.nextContentLine()
			if err != nil {
				return nil, err
			}
			if cl == nil || cl.indent <= indent {
				value = p.nullNode(valPos)
				// do not consume the line
				p.s.moveBackTo(valPos.Line)
			} else {
				value, err = p.parseBlockNode(indent+1, false)
				if err != nil {
					return nil, err
				}
				if value == nil {
					value = p.nullNode(valPos)
				}
			}
		} else {
			sameLine = true
			value, err = p.parseValue(indent)
			if err != nil {
				return nil, err
			}
			if value == nil {
				value = p.nullNode(valPos)
			}
		}
		if value.endLine < valPos.Line {
			value.endLine = valPos.Line
		}
		m.endLine = p.s.line
		if prev, ok := keys[key.value]; ok {
			return nil, syntaxErrf(p.src, key.pos, key.endLine+1, "mapping key %q already defined at [%d:%d]", key.value, prev.Line, prev.Col)
		}
		keys[key.value] = key.pos
		m.pairs = append(m.pairs, pair{key: key, value: value})
		// find the next entry
		cl, err := p.nextContentLine()
		if err != nil {
			return nil, err
		}
		if cl == nil {
			break
		}
		if cl.indent < indent {
			break
		}
		if cl.indent > indent {
			if sameLine {
				return nil, syntaxErrf(p.src, value.pos, value.endLine+1, "mapping value is not allowed in this context")
			}
			return nil, syntaxErrf(p.src, cl.pos, cl.pos.Line+1, "mapping value is not allowed in this context")
		}
		if !cl.isMap {
			return nil, syntaxErrf(p.src, cl.pos, cl.pos.Line+1, "non-map value is specified")
		}
	}
	return m, nil
}

// moveBackTo moves the scanner to the first content character of the given line
func (p *parser) moveBackTo(line int) {
	for p.s.line > line {
		p.s.moveToLineStart()
		p.s.pos = p.s.lineStart()
		p.s.col = 1
		if p.s.line > line {
			// step back over the newline
			p.s.pos--
			p.s.line--
		}
	}
	p.s.moveToLineStart()
	i := p.s.lineStart()
	rs := p.s.runes()
	for p.s.pos < len(rs) && (rs[p.s.pos] == ' ') {
		p.s.next()
	}
}

func (p *parser) nullNode(pos Position) *node {
	return &node{kind: kindScalar, tag: typeNull, value: "", pos: pos, endLine: pos.Line}
}
