// moveBackTo moves the scanner to the first content character of the given line
func (p *parser) moveBackTo(line int) {
	for p.s.line > line {
		p.s.moveToLineStart()
		p.s.pos = p.s.lineStart()
		p.s.col = 1
		if p.s.line > line {
