package yaml

import (
	"strconv"
	"strings"
)

// parseKey parses a mapping key
func (p *parser) parseKey() (*node, error) {
	p.skipBlanksAndComments()
	if p.s.eof() {
		return nil, nil
	}
	pos := p.s.position()
	switch p.s.peek() {
	case '"':
		n, err := p.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		p.skipInlineSpaces()
		n.endLine = n.pos.Line
		return n, nil
	case '\'':
		n, err := p.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		p.skipInlineSpaces()
		n.endLine = n.pos.Line
		return n, nil
	case '?':
		return nil, nil
	case ':':
		return nil, nil
	case '-':
		return nil, nil
	}
	// plain scalar key: ends at ": " or ":" at end of line
	end, ok := p.keyColonIndex()
	if !ok {
		return nil, nil
	}
	text := p.textBetween(p.s.pos, end)
	key := &node{kind: kindScalar, tag: scalarType(text), value: text, pos: pos}
	return key, nil
}

// keyColonIndex finds the index of the ':' that terminates a key on the current line
func (p *parser) keyColonIndex() (int, bool) {
	rs := p.s.runes()
	i := p.s.pos
	end := p.s.lineEnd()
	depth := 0
	for i < end {
		switch rs[i] {
		case '"', '\'':
			q := rs[i]
			i++
			for i < end {
				if rs[i] == '\\' && q == '"' {
					i += 2
					continue
				}
				if rs[i] == q {
					break
				}
				i++
			}
			if i >= end {
				return 0, false
			}
		case '[', '{':
			depth++
		case ']', '}':
			depth--
		case '#':
			if i > p.s.pos && (rs[i-1] == ' ' || rs[i-1] == '\t') {
				return 0, false
			}
		case ':':
			if depth == 0 {
				if i+1 >= len(rs) || rs[i+1] == ' ' || rs[i+1] == '\n' || rs[i+1] == '\t' {
					return i, true
				}
			}
		}
		i++
	}
	return 0, false
}

func (p *parser) textBetween(start, end int) string {
	rs := p.s.runes()
	return strings.TrimRight(string(rs[start:end]), " \t")
}

func (p *parser) skipInlineSpaces() {
	for !p.s.eof() && (p.s.peek() == ' ' || p.s.peek() == '\t') {
		p.s.next()
	}
}

// parseScalar parses a scalar in block context (may span lines)
func (p *parser) parseScalar(indent int) (*node, error) {
	pos := p.s.position()
	switch p.s.peek() {
	case '"':
		n, err := p.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		n.endLine = p.s.line
		return n, nil
	case '\'':
		n, err := p.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		n.endLine = p.s.line
		return n, nil
	}
	return p.parsePlainScalar(indent, false)
}

// parseValue parses a value in a mapping on the same line
func (p *parser) parseValue(indent int) (*node, error) {
	anchor, tag, err := p.parseProperties(indent)
	if err != nil {
		return nil, err
	}
	if p.s.atLineEnd() || p.s.restIsBlankOrComment() {
		n := p.nullNode(p.s.position())
		p.applyProps(n, anchor, tag)
		return n, nil
	}
	var n *node
	switch p.s.peek() {
	case '*':
		n, err = p.parseAlias()
	case '{', '[':
		n, err = p.parseFlow()
	case '|', '>':
		n, err = p.parseBlockScalar(indent)
	case '"':
		n, err = p.parseDoubleQuoted()
		if err == nil {
			// trailing content after a quoted value is an error
			p.skipInlineSpaces()
			if !p.s.atLineEnd() && !p.s.restIsBlankOrComment() {
				pos := p.s.position()
				err = syntaxErrf(p.src, pos, pos.Line+1, "value is not allowed in this context. map key-value is pre-defined")
			}
		}
	case '\'':
		n, err = p.parseSingleQuoted()
		if err == nil {
			p.skipInlineSpaces()
			if !p.s.atLineEnd() && !p.s.restIsBlankOrComment() {
				pos := p.s.position()
				err = syntaxErrf(p.src, pos, pos.Line+1, "value is not allowed in this context. map key-value is pre-defined")
			}
		}
	default:
		n, err = p.parsePlainScalar(indent, true)
	}
	if err != nil {
		return nil, err
	}
	if tag != "" {
		if tag == "!!str" || tag == "!x" {
			// keep as string
		} else if n.kind != kindScalar {
			pos := p.s.position()
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "unexpected scalar value type")
		}
	}
	n.endLine = p.s.line
	p.applyProps(n, anchor, tag)
	return n, nil
}

func (p *parser) applyProps(n *node, anchor, tag string) {
	if tag != "" {
		n.tagText = tag
	}
	if anchor != "" {
		p.anchors[anchor] = n
		n.anchor = anchor
	}
}

// parseProperties parses anchor and tag properties
func (p *parser) parseProperties(indent int) (string, string, error) {
	anchor := ""
	tag := ""
	for {
		switch p.s.peek() {
		case '&':
			p.s.next()
			start := p.s.pos
			for !p.s.eof() && isWordChar(p.s.peek()) {
				p.s.next()
			}
			anchor = string(p.s.runes()[start:p.s.pos])
			p.skipInlineSpaces()
			if p.s.atLineEnd() || p.s.restIsBlankOrComment() {
				if anchor != "" {
					// anchor with no value on the same line
					return anchor, tag, syntaxErrf(p.src, Position{Line: p.s.line - 0, Col: 1}, p.s.line+1, "undefined anchor value")
				}
			}
		case '!':
			start := p.s.pos
			for !p.s.eof() && p.s.peek() != ' ' && p.s.peek() != '\n' && p.s.peek() != '\t' {
				p.s.next()
			}
			tag = string(p.s.runes()[start:p.s.pos])
			p.skipInlineSpaces()
			if tag == "!!map" || tag == "!!seq" {
				if p.s.atLineEnd() || p.s.restIsBlankOrComment() {
					// tagged null
					return anchor, tag, nil
				}
			}
		default:
			return anchor, tag, nil
		}
	}
}

func isWordChar(r rune) bool {
	return r == '-' || r == '_' || r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9'
}

// parseAlias parses an alias reference
func (p *parser) parseAlias() (*node, error) {
	pos := p.s.position()
	p.s.next() // consume '*'
	start := p.s.pos
	for !p.s.eof() && isWordChar(p.s.peek()) {
		p.s.next()
	}
	name := string(p.s.runes()[start:p.s.pos])
	if n, ok := p.anchors[name]; ok {
		cp := *n
		cp.pos = pos
		cp.endLine = p.s.line
		return &cp, nil
	}
	return nil, syntaxErrf(p.src, pos, p.s.line+1, "could not find alias %q", name)
}

// parsePlainScalar parses a plain scalar, possibly spanning multiple lines
func (p *parser) parsePlainScalar(indent int, inValue bool) (*node, error) {
	pos := p.s.position()
	end := p.plainScalarEnd()
	value := p.textBetween(p.s.pos, end)
	// advance to the end
	for p.s.pos < end {
		p.s.next()
	}
	p.skipTrailingSpacesAndComment()
	endLine := p.s.line
	// multi-line continuation
	for {
		cl, ok := p.peekNextLine()
		if !ok {
			break
		}
		if cl.indent <= indent {
			break
		}
		if cl.isMap || cl.isSeq {
			if inValue {
				return nil, syntaxErrf(p.src, pos, endLine+1, "mapping value is not allowed in this context")
			}
			break
		}
		p.s.skipToNextLine()
		p.s.skipBlanksAndComments()
		lineEnd := p.plainScalarEnd()
		part := strings.TrimSpace(p.textBetween(p.s.pos, lineEnd))
		if part == "" {
			break
		}
		for p.s.pos < lineEnd {
			p.s.next()
		}
		p.skipTrailingSpacesAndComment()
		endLine = p.s.line
		value = value + " " + part
	}
	n := &node{kind: kindScalar, tag: scalarType(value), value: value, pos: pos, endLine: endLine}
	return n, nil
}

// plainScalarEnd returns the rune index where the plain scalar on the current line ends
func (p *parser) plainScalarEnd() int {
	rs := p.s.runes()
	i := p.s.pos
	end := p.s.lineEnd()
	last := i
	for i < end {
		r := rs[i]
		if r == '#' && i > p.s.pos && (rs[i-1] == ' ' || rs[i-1] == '\t') {
			break
		}
		if r != ' ' && r != '\t' {
			last = i + 1
		}
		i++
	}
	return last
}

func (p *parser) skipTrailingSpacesAndComment() {
	for !p.s.eof() && p.s.peek() == ' ' {
		p.s.next()
	}
	if p.s.peek() == '#' {
		for !p.s.eof() && p.s.peek() != '\n' {
			p.s.next()
		}
	}
}

// parseQuoted reads a quoted scalar
func (p *parser) parseDoubleQuoted() (*node, error) {
	pos := p.s.position()
	start := p.s.pos
	p.s.next() // consume opening quote
	rs := p.s.runes()
	var sb strings.Builder
	for {
		if p.s.eof() {
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of double-quoted text")
		}
		r := p.s.peek()
		if r == '\n' {
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of double-quoted text")
		}
		if r == '"' {
			p.s.next()
			break
		}
		if r == '\\' {
			p.s.next()
			e := p.s.peek()
			switch e {
			case 'n':
				sb.WriteRune('\n')
			case 't':
				sb.WriteRune('\t')
			case 'r':
				sb.WriteRune('\r')
			case '0':
				sb.WriteRune(0)
			case 'a':
				sb.WriteRune(7)
			case 'b':
				sb.WriteRune(8)
			case 'f':
				sb.WriteRune(12)
			case 'v':
				sb.WriteRune(11)
			case 'e':
				sb.WriteRune(27)
			case '"':
				sb.WriteRune('"')
			case '\\':
				sb.WriteRune('\\')
			case '/':
				sb.WriteRune('/')
			case ' ':
				sb.WriteRune(' ')
			case 'u':
				p.s.next()
				hex := p.readHex(4)
				if hex < 0 {
					return nil, syntaxErrf(p.src, pos, pos.Line+1, "found unknown escape character")
				}
				sb.WriteRune(rune(hex))
			case 'x':
				p.s.next()
				hex := p.readHex(2)
				if hex < 0 {
					return nil, syntaxErrf(p.src, pos, pos.Line+1, "found unknown escape character")
				}
				sb.WriteRune(rune(hex))
			default:
				if p.s.eof() || e == '\n' {
					return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of double-quoted text")
				}
				return nil, syntaxErrf(p.src, p.s.position(), p.s.line+1, "found unknown escape character '%c'", e)
			}
			p.s.next()
			continue
		}
		sb.WriteRune(r)
		p.s.next()
	}
	_ = start
	_ = rs
	value := sb.String()
	return &node{kind: kindScalar, tag: scalarType(value), value: value, quoted: true, pos: pos}, nil
}

func (p *parser) readHex(n int) int {
	v := 0
	for i := 0; i < n; i++ {
		r := p.s.peek()
		d, ok := hexDigit(r)
		if !ok {
			return -1
		}
		v = v*16 + d
		p.s.next()
	}
	return v
}

func hexDigit(r rune) (int, bool) {
	switch {
	case r >= '0' && r <= '9':
		return int(r - '0'), true
	case r >= 'a' && r <= 'f':
		return int(r-'a') + 10, true
	case r >= 'A' && r <= 'F':
		return int(r-'A') + 10, true
	}
	return 0, false
}

func rune(v int) rune { return rune(v) }

func (p *parser) parseSingleQuoted() (*node, error) {
	pos := p.s.position()
	p.s.next() // consume opening quote
	var sb strings.Builder
	for {
		if p.s.eof() || p.s.peek() == '\n' {
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of single-quoted text")
		}
		r := p.s.peek()
		if r == '\'' {
			if p.s.peekAt(1) == '\'' {
				sb.WriteRune('\'')
				p.s.next()
				p.s.next()
				continue
			}
			p.s.next()
			break
		}
		sb.WriteRune(r)
		p.s.next()
	}
	value := sb.String()
	return &node{kind: kindScalar, tag: scalarType(value), value: value, quoted: true, pos: pos}, nil
}

// parseBlockScalar parses a literal (|) or folded (>) scalar
func (p *parser) parseBlockScalar(indent int) (*node, error) {
	pos := p.s.position()
	folded := p.s.peek() == '>'
	p.s.next()
	chomp := byte('c')
	for !p.s.eof() && p.s.peek() != '\n' && p.s.peek() != '#' {
		r := p.s.peek()
		if r == '-' {
			chomp = '-'
		} else if r == '+' {
			chomp = '+'
		}
		p.s.next()
	}
	for !p.s.eof() && p.s.peek() != '\n' {
		p.s.next()
	}
	if !p.s.eof() {
		p.s.next()
	}
	// gather lines
	var lines []string
	blockIndent := -1
	for !p.s.eof() {
		st := p.save()
		p.s.moveToLineStart()
		lineIndent, tab := p.s.indentOf()
		lineEnd := p.s.lineEnd()
		rs := p.s.runes()
		content := ""
		if lineIndent < len(rs) && rs[p.s.lineStart()+lineIndent] != '\n' {
			content = string(rs[p.s.lineStart()+lineIndent : lineEnd])
		}
		blank := strings.TrimSpace(content) == ""
		if tab && !blank {
			p.restore(st)
			break
		}
		if !blank {
			if blockIndent < 0 {
				if lineIndent <= indent {
					p.restore(st)
					break
				}
				blockIndent = lineIndent
			}
			if lineIndent < blockIndent {
				p.restore(st)
				break
			}
			lines = append(lines, content[blockIndent:])
			p.restore(st)
			p.s.skipToNextLine()
			continue
		}
		// blank line
		lines = append(lines, "")
		p.restore(st)
		p.s.skipToNextLine()
	}
	// trim trailing blank lines according to chomping
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	var value string
	if folded {
		var parts []string
		cur := ""
		for _, l := range lines {
			if l == "" {
				parts = append(parts, cur)
				cur = ""
				continue
			}
			if cur == "" {
				cur = l
			} else {
				cur = cur + " " + l
			}
		}
		parts = append(parts, cur)
		value = strings.Join(parts, "\n")
	} else {
		value = strings.Join(lines, "\n")
	}
	if chomp != '-' {
		value += "\n"
	}
	if chomp == 'c' {
		// clip: single trailing newline (already added)
	}
	return &node{kind: kindScalar, tag: typeStr, value: value, pos: pos}, nil
}

