// parsePlainScalar parses a plain scalar, possibly spanning multiple lines
func (p *parser) parsePlainScalar(indent int, inValue bool) (*node, error) {
	pos := p.s.position()
	end := p.plainScalarEnd()
	value := p.textBetween(p.s.pos, end)
	// advance to the end
	for p.s.pos < end {
		p.s.next()
	}
	p.skipTrailingSpacesAndComment()
	endLine := p.s.line
	// multi-line continuation
	for {
		cl, ok := p.peekNextLine()
		if !ok {
			break
		}
		if cl.indent <= indent {
			break
		}
		if cl.isMap || cl.isSeq {
			if inValue {
				return nil, syntaxErrf(p.src, pos, endLine+1, "mapping value is not allowed in this context")
			}
			break
		}
		p.s.skipToNextLine()
		p.s.skipBlanksAndComments()
		lineEnd := p.plainScalarEnd()
		part := strings.TrimSpace(p.textBetween(p.s.pos, lineEnd))
		if part == "" {
			break
		}
		for p.s.pos < lineEnd {
			p.s.next()
		}
		p.skipTrailingSpacesAndComment()
		endLine = p.s.line
		value = value + " " + part
	}
	n := &node{kind: kindScalar, tag: scalarType(value), value: value, pos: pos, endLine: endLine}
	return n, nil
}

// plainScalarEnd returns the rune index where the plain scalar on the current line ends
func (p *parser) plainScalarEnd() int {
	rs := p.s.runes()
	i := p.s.pos
	end := p.s.lineEnd()
	last := i
	for i < end {
		r := rs[i]
		if r == '#' && i > p.s.pos && (rs[i-1] == ' ' || rs[i-1] == '\t') {
			break
		}
		if r != ' ' && r != '\t' {
			last = i + 1
		}
		i++
	}
	return last
}

func (p *parser) skipTrailingSpacesAndComment() {
	for !p.s.eof() && p.s.peek() == ' ' {
		p.s.next()
	}
	if p.s.peek() == '#' {
		for !p.s.eof() && p.s.peek() != '\n' {
			p.s.next()
		}
	}
}

// parseQuoted reads a quoted scalar
func (p *parser) parseDoubleQuoted() (*node, error) {
	pos := p.s.position()
	start := p.s.pos
	p.s.next() // consume opening quote
	rs := p.s.runes()
	var sb strings.Builder
	for {
		if p.s.eof() {
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of double-quoted text")
		}
		r := p.s.peek()
		if r == '\n' {
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of double-quoted text")
		}
		if r == '"' {
			p.s.next()
			break
		}
		if r == '\\' {
			p.s.next()
			e := p.s.peek()
			switch e {
			case 'n':
				sb.WriteRune('\n')
			case 't':
				sb.WriteRune('\t')
			case 'r':
				sb.WriteRune('\r')
			case '0':
				sb.WriteRune(0)
			case 'a':
				sb.WriteRune(7)
			case 'b':
				sb.WriteRune(8)
			case 'f':
				sb.WriteRune(12)
			case 'v':
				sb.WriteRune(11)
			case 'e':
				sb.WriteRune(27)
			case '"':
				sb.WriteRune('"')
			case '\\':
				sb.WriteRune('\\')
			case '/':
				sb.WriteRune('/')
			case ' ':
				sb.WriteRune(' ')
			case 'u':
				p.s.next()
				hex := p.readHex(4)
				if hex < 0 {
					return nil, syntaxErrf(p.src, pos, pos.Line+1, "found unknown escape character")
				}
				sb.WriteRune(rune(hex))
			case 'x':
				p.s.next()
				hex := p.readHex(2)
				if hex < 0 {
					return nil, syntaxErrf(p.src, pos, pos.Line+1, "found unknown escape character")
				}
				sb.WriteRune(rune(hex))
			default:
				if p.s.eof() || e == '\n' {
					return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of double-quoted text")
				}
				return nil, syntaxErrf(p.src, p.s.position(), p.s.line+1, "found unknown escape character '%c'", e)
			}
			p.s.next()
			continue
		}
		sb.WriteRune(r)
		p.s.next()
	}
	_ = start
	_ = rs
	value := sb.String()
	return &node{kind: kindScalar, tag: scalarType(value), value: value, quoted: true, pos: pos}, nil
}

func (p *parser) readHex(n int) int {
	v := 0
	for i := 0; i < n; i++ {
		r := p.s.peek()
		d, ok := hexDigit(r)
		if !ok {
			return -1
		}
		v = v*16 + d
		p.s.next()
	}
	return v
}

func hexDigit(r rune) (int, bool) {
	switch {
	case r >= '0' && r <= '9':
		return int(r - '0'), true
	case r >= 'a' && r <= 'f':
		return int(r-'a') + 10, true
	case r >= 'A' && r <= 'F':
		return int(r-'A') + 10, true
	}
	return 0, false
}

func rune(v int) rune { return rune(v) }

func (p *parser) parseSingleQuoted() (*node, error) {
	pos := p.s.position()
	p.s.next() // consume opening quote
	var sb strings.Builder
	for {
		if p.s.eof() || p.s.peek() == '\n' {
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find end character of single-quoted text")
		}
		r := p.s.peek()
		if r == '\'' {
			if p.s.peekAt(1) == '\'' {
				sb.WriteRune('\'')
				p.s.next()
				p.s.next()
				continue
			}
			p.s.next()
			break
		}
		sb.WriteRune(r)
		p.s.next()
	}
	value := sb.String()
	return &node{kind: kindScalar, tag: scalarType(value), value: value, quoted: true, pos: pos}, nil
}

// parseBlockScalar parses a literal (|) or folded (>) scalar
func (p *parser) parseBlockScalar(indent int) (*node, error) {
	pos := p.s.position()
	folded := p.s.peek() == '>'
	p.s.next()
	chomp := byte('c')
	for !p.s.eof() && p.s.peek() != '\n' && p.s.peek() != '#' {
		r := p.s.peek()
		if r == '-' {
			chomp = '-'
		} else if r == '+' {
			chomp = '+'
		}
		p.s.next()
	}
	for !p.s.eof() && p.s.peek() != '\n' {
		p.s.next()
	}
	if !p.s.eof() {
		p.s.next()
	}
	// gather lines
	var lines []string
	blockIndent := -1
	for !p.s.eof() {
		st := p.save()
		p.s.moveToLineStart()
		lineIndent, tab := p.s.indentOf()
		lineEnd := p.s.lineEnd()
		rs := p.s.runes()
		content := ""
		if lineIndent < len(rs) && rs[p.s.lineStart()+lineIndent] != '\n' {
			content = string(rs[p.s.lineStart()+lineIndent : lineEnd])
		}
		blank := strings.TrimSpace(content) == ""
		if tab && !blank {
			p.restore(st)
			break
		}
		if !blank {
			if blockIndent < 0 {
				if lineIndent <= indent {
					p.restore(st)
					break
				}
				blockIndent = lineIndent
			}
			if lineIndent < blockIndent {
				p.restore(st)
				break
			}
			lines = append(lines, content[blockIndent:])
			p.restore(st)
			p.s.skipToNextLine()
			continue
		}
		// blank line
		lines = append(lines, "")
		p.restore(st)
		p.s.skipToNextLine()
	}
	// trim trailing blank lines according to chomping
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	var value string
	if folded {
		var parts []string
		cur := ""
		for _, l := range lines {
			if l == "" {
				parts = append(parts, cur)
				cur = ""
				continue
			}
			if cur == "" {
				cur = l
			} else {
				cur = cur + " " + l
			}
		}
		parts = append(parts, cur)
		value = strings.Join(parts, "\n")
	} else {
		value = strings.Join(lines, "\n")
	}
	if chomp != '-' {
		value += "\n"
	}
	if chomp == 'c' {
		// clip: single trailing newline (already added)
	}
	return &node{kind: kindScalar, tag: typeStr, value: value, pos: pos}, nil
}

