// parseBlockScalar parses a literal (|) or folded (>) scalar
func (p *parser) parseBlockScalar(indent int) (*node, error) {
	pos := p.s.position()
	folded := p.s.peek() == '>'
	p.s.next()
	chomp := byte('c')
	for !p.s.eof() && p.s.peek() != '\n' && p.s.peek() != '#' {
		r := p.s.peek()
		if r == '-' {
			chomp = '-'
		} else if r == '+' {
			chomp = '+'
		}
		p.s.next()
	}
	for !p.s.eof() && p.s.peek() != '\n' {
		p.s.next()
	}
	if !p.s.eof() {
		p.s.next()
	}
	// gather lines
	var lines []string
	blockIndent := -1
	for !p.s.eof() {
		st := p.save()
		p.s.moveToLineStart()
		lineIndent, tab := p.s.indentOf()
		lineEnd := p.s.lineEnd()
		rs := p.s.runes()
		content := ""
		if lineIndent < len(rs) && rs[p.s.lineStart()+lineIndent] != '\n' {
			content = string(rs[p.s.lineStart()+lineIndent : lineEnd])
		}
		blank := strings.TrimSpace(content) == ""
		if tab && !blank {
			p.restore(st)
			break
		}
		if !blank {
			if blockIndent < 0 {
				if lineIndent <= indent {
					p.restore(st)
					break
				}
				blockIndent = lineIndent
			}
			if lineIndent < blockIndent {
				p.restore(st)
				break
			}
			lines = append(lines, content[blockIndent:])
			p.restore(st)
			p.s.skipToNextLine()
			continue
		}
		// blank line
		lines = append(lines, "")
		p.restore(st)
		p.s.skipToNextLine()
	}
	// trim trailing blank lines according to chomping
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	var value string
	if folded {
		var parts []string
		cur := ""
		for _, l := range lines {
			if l == "" {
				parts = append(parts, cur)
				cur = ""
				continue
			}
			if cur == "" {
				cur = l
			} else {
				cur = cur + " " + l
			}
		}
		parts = append(parts, cur)
		value = strings.Join(parts, "\n")
	} else {
		value = strings.Join(lines, "\n")
	}
	if chomp != '-' {
		value += "\n"
	}
	if chomp == 'c' {
		// clip: single trailing newline (already added)
	}
	return &node{kind: kindScalar, tag: typeStr, value: value, pos: pos}, nil
