func (p *parser) skipFlowSpace() {
	for !p.s.eof() {
		r := p.s.peek()
		if r == ' ' || r == '\t' || r == '\n' {
			p.s.next()
			continue
		}
		if r == '#' {
			for !p.s.eof() && p.s.peek() != '\n' {
				p.s.next()
			}
			continue
		}
		return
	}
}

