		if p.s.peek() == '}' {
			p.s.next()
			break
		}
		key, err := p.parseFlowKey(first)
		if err != nil {
			return nil, err
		}
		if key == nil {
			pos := p.s.position()
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find flow map content")
		}
		first = false
		p.skipFlowSpace()
		value := p.nullNode(p.s.position())
		if p.s.peek() == ':' {
			p.s.next()
			p.skipFlowSpace()
			if p.s.eof() {
				return nil, syntaxErrf(p.src, openPos, p.s.line+1, "could not find flow mapping end token '}'")
			}
			if p.s.peek() != '}' && p.s.peek() != ',' {
				v, err := p.parseFlowValue()
				if err != nil {
					return nil, err
				}
				if v == nil {
					pos := p.s.position()
					return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find flow map content")
				}
				value = v
			}
		}
		if prev, ok := keys[key.value]; ok {
			return nil, syntaxErrf(p.src, key.pos, key.pos.Line+1, "mapping key %q already defined at [%d:%d]", key.value, prev.Line, prev.Col)
		}
		keys[key.value] = key.pos
		m.pairs = append(m.pairs, pair{key: key, value: value})
		p.skipFlowSpace()
		if p.s.eof() {
			return nil, syntaxErrf(p.src, openPos, p.s.line+1, "could not find flow mapping end token '}'")
		}
		if p.s.peek() == ',' {
			p.s.next()
			continue
		}
		if p.s.peek() == '}' {
			p.s.next()
			break
		}
		pos := p.s.position()
		return nil, syntaxErrf(p.src, pos, pos.Line+1, "could not find flow map content")
	}
	m.endLine = p.s.line
	return m, nil
}

// parseFlowKey parses a key inside a flow mapping
func (p *parser) parseFlowKey(first bool) (*node, error) {
	pos := p.s.position()
	switch p.s.peek() {
	case '"':
		n, err := p.parseDoubleQuoted()
		if err != nil {
			return nil, err
		}
		return n, nil
	case '\'':
		n, err := p.parseSingleQuoted()
		if err != nil {
			return nil, err
		}
		return n, nil
	case ',':
		if first {
			return nil, nil
		}
		return nil, nil
	case '?':
		return nil, nil
	case ':':
		return nil, nil
	}
	// plain scalar ending at ':' , ',' or '}' or end of line
	end, ok := p.flowKeyEnd()
	if !ok {
		return nil, nil
	}
	text := p.textBetween(p.s.pos, end)
	if text == "" {
		return nil, nil
	}
	n := &node{kind: kindScalar, tag: scalarType(text), value: text, pos: pos}
	for p.s.pos < end {
		p.s.next()
	}
	return n, nil
}

func (p *parser) flowKeyEnd() (int, bool) {
	rs := p.s.runes()
	i := p.s.pos
	end := p.s.lineEnd()
	last := i
	for i < end {
		r := rs[i]
		if r == ':' || r == ',' || r == '}' {
			if r == ':' && (i+1 >= len(rs) || rs[i+1] != ' ' && rs[i+1] != '\n' && rs[i+1] != '\t' && rs[i+1] != ',' && rs[i+1] != '}') {
				// part of a scalar (not a separator)
				i++
				continue
			}
			return i, true
		}
		if r != ' ' && r != '\t' {
			last = i + 1
		}
		i++
	}
	return last, last > p.s.pos
}

// parseFlowValue parses a value inside a flow collection
func (p *parser) parseFlowValue() (*node, error) {
	pos := p.s.position()
	anchor, tag, err := p.parseProperties(0)
	if err != nil {
		return nil, err
	}
	if p.s.eof() {
		return nil, nil
	}
	var n *node
	switch p.s.peek() {
	case '*':
		n, err = p.parseAlias()
	case '{', '[':
		n, err = p.parseFlow()
	case '"':
		n, err = p.parseDoubleQuoted()
	case '\'':
		n, err = p.parseSingleQuoted()
	case ',':
		n = nil
	case '}', ']':
		n = nil
	default:
		n, err = p.parseFlowScalar()
	}
	if err != nil {
		return nil, err
	}
	if n == nil {
		return nil, nil
	}
	if tag != "" {
		if n.kind != kindScalar {
			pos := p.s.position()
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "unexpected scalar value type")
		}
		n.tagText = tag
	}
	if anchor != "" {
		p.anchors[anchor] = n
	}
	n.endLine = p.s.line
	return n, nil
}

// parseFlowScalar parses a single-line plain scalar in flow context
func (p *parser) parseFlowScalar() (*node, error) {
	pos := p.s.position()
	end := p.flowScalarEnd()
	value := p.textBetween(p.s.pos, end)
	for p.s.pos < end {
		p.s.next()
	}
	if value == "" {
		return nil, nil
	}
	return &node{kind: kindScalar, tag: scalarType(value), value: value, pos: pos}, nil
}

func (p *parser) flowScalarEnd() int {
	rs := p.s.runes()
	i := p.s.pos
	end := p.s.lineEnd()
	last := i
	for i < end {
		r := rs[i]
		if r == ',' || r == ']' || r == '}' {
			break
		}
		if r == '#' && i > p.s.pos && (rs[i-1] == ' ' || rs[i-1] == '\t') {
			break
		}
		if r != ' ' && r != '\t' {
			last = i + 1
		}
		i++
	}
	return last
}

func (p *parser) parseFlowSequence() (*node, error) {
	openPos := p.s.position()
	p.s.next() // consume '['
	seq := &node{kind: kindSequence, pos: openPos, tag: typeSeq}
	first := true
	for {
		p.skipFlowSpace()
		if p.s.eof() {
			return nil, syntaxErrf(p.src, openPos, p.s.line+1, "sequence end token ']' not found")
		}
		if p.s.peek() == ']' {
			p.s.next()
			break
		}
		if p.s.peek() == ',' {
			pos := p.s.position()
			if first {
				return nil, syntaxErrf(p.src, pos, pos.Line+1, "expected sequence element, but found ','")
			}
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "unexpected scalar value type")
		}
		v, err := p.parseFlowValue()
		if err != nil {
			return nil, err
		}
		if v == nil {
			pos := p.s.position()
			if first {
				return nil, syntaxErrf(p.src, pos, pos.Line+1, "expected sequence element, but found ','")
			}
			return nil, syntaxErrf(p.src, pos, pos.Line+1, "unexpected scalar value type")
		}
		first = false
		seq.items = append(seq.items, v)
		p.skipFlowSpace()
		if p.s.eof() {
			return nil, syntaxErrf(p.src, openPos, p.s.line+1, "sequence end token ']' not found")
		}
		if p.s.peek() == ',' {
			p.s.next()
			continue
		}
		if p.s.peek() == ']' {
			p.s.next()
			break
		}
		pos := p.s.position()
		return nil, syntaxErrf(p.src, pos, pos.Line+1, "',' or ']' must be specified")
	}
	seq.endLine = p.s.line
	return seq, nil
}

// skipFlowSpace skips spaces, newlines and comments inside a flow collection
func (p *parser) skipFlowSpace() {
	for !p.s.eof() {
		r := p.s.peek()
		if r == ' ' || r == '\t' || r == '\n' {
			p.s.next()
			continue
		}
		if r == '#' {
			for !p.s.eof() && p.s.peek() != '\n' {
				p.s.next()
			}
			continue
		}
		return
	}
}

