	"chamber/types"
	"chamber/yaml"
)

// Parameters writes the parameters in the given format
func Parameters(w io.Writer, parameters []types.Parameter, format string) error {
	switch strings.ToLower(format) {
	case "json":
		return printJSON(w, parameters)
	case "yaml":
		return printYAML(w, parameters)
	case "java-properties":
		return printJavaProperties(w, parameters)
	case "csv":
		return printDelimited(w, parameters, ',')
	case "tsv":
		return printDelimited(w, parameters, '\t')
	case "dotenv":
		return printDotenv(w, parameters)
	case "tfvars":
		return printTerraformVars(w, parameters)
	default:
		return fmt.Errorf("Unsupported export format: %s", format)
	}
}

func sortedParameters(parameters []types.Parameter) []types.Parameter {
	out := make([]types.Parameter, len(parameters))
	copy(out, parameters)
	sort.SliceStable(out, func(i, j int) bool { return out[i].Key < out[j].Key })
	return out
}

func printJSON(w io.Writer, parameters []types.Parameter) error {
	data := make(map[string]string, len(parameters))
	for _, parameter := range parameters {
		data[parameter.Key] = parameter.Value
	}
	return json.NewEncoder(w).Encode(data)
}

func printYAML(w io.Writer, parameters []types.Parameter) error {
	data := make(map[string]string, len(parameters))
	for _, parameter := range parameters {
		data[parameter.Key] = parameter.Value
	}
	b, err := yaml.MarshalMap(data)
	if err != nil {
		return err
	}
	_, err = w.Write(b)
	return err
}

func printJavaProperties(w io.Writer, parameters []types.Parameter) error {
	for _, parameter := range sortedParameters(parameters) {
		fmt.Fprintf(w, "%s=%s\n", escapeJavaKey(parameter.Key), escapeJavaValue(parameter.Value))
	}
	return nil
}

func escapeJavaKey(k string) string {
	return strings.NewReplacer("\\", "\\\\", "=", "\\=", ":", "\\=", " ", "\\ ").Replace(k)
}

func escapeJavaValue(v string) string {
	return strings.NewReplacer("\\", "\\\\", "\n", "\\n", "\t", "\\t", "\r", "\\r").Replace(v)
}

func printDelimited(w io.Writer, parameters []types.Parameter, sep rune) error {
	for _, parameter := range sortedParameters(parameters) {
		fmt.Fprintf(w, "%s%c%s\n", quoteDelimited(parameter.Key, sep), sep, quoteDelimited(parameter.Value, sep))
	}
	return nil
}

func quoteDelimited(s string, sep rune) string {
	if strings.ContainsRune(s, sep) || strings.Contains(s, "\"") || strings.Contains(s, "\n") {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

func printDotenv(w io.Writer, parameters []types.Parameter) error {
	for _, parameter := range sortedParameters(parameters) {
		key := strings.ToUpper(strings.NewReplacer(".", "_", "-", "_", " ", "_").Replace(parameter.Key))
		value := parameter.Value
		if strings.ContainsAny(value, " \t\n\"'") {
			value = "\"" + strings.NewReplacer("\\", "\\\\", "\"", "\\\"", "\n", "\\n").Replace(value) + "\""
		}
		fmt.Fprintf(w, "%s=%s\n", key, value)
	}
	return nil
}

func printTerraformVars(w io.Writer, parameters []types.Parameter) error {
	for _, parameter := range sortedParameters(parameters) {
		key := strings.NewReplacer(".", "_", "-", "_", " ", "_").Replace(parameter.Key)
		fmt.Fprintf(w, "%s = \"%s\"\n", key, parameter.Value)
	}
	return nil
}

