package yaml

import (
	"sort"
	"strconv"
	"strings"
)

// MarshalMap serializes a string map as yaml
func MarshalMap(data map[string]string) ([]byte, error) {
	keys := make([]string, 0, len(data))
	for k := range data {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	if len(keys) == 0 {
		return []byte("{}\n"), nil
	}
	var sb strings.Builder
	for _, k := range keys {
		sb.WriteString(encodeScalar(k))
		sb.WriteString(":")
		v := data[k]
		if strings.Contains(v, "\n") {
			sb.WriteString(" |-\n")
			for _, line := range strings.Split(strings.TrimSuffix(v, "\n"), "\n") {
				sb.WriteString("  ")
				sb.WriteString(line)
				sb.WriteString("\n")
			}
			continue
		}
		sb.WriteString(" ")
		sb.WriteString(encodeScalar(v))
		sb.WriteString("\n")
	}
	return []byte(sb.String()), nil
}

func encodeScalar(s string) string {
	if s == "" {
		return `""`
	}
	if needsQuote(s) {
		return strconv.Quote(s)
	}
	return s
}

func needsQuote(s string) bool {
	if strings.ContainsAny(s, ":#{}[],&*!|>'\"%@`") {
		return true
	}
	if strings.ContainsAny(s, "\n\t") {
		return true
	}
	if strings.TrimSpace(s) != s {
		return true
	}
	switch scalarType(s) {
	case typeNull, typeBool, typeInt, typeFloat, typeInf, typeNan:
		return true
	}
	return false
}
