// awsCredentials holds resolved AWS credentials
type awsCredentials struct {
	AccessKeyID     string
	SecretAccessKey string
	SessionToken    string
}

// awsConfig holds the resolved AWS configuration
type awsConfig struct {
	Region      string
	Creds       *awsCredentials
	MaxAttempts int
	RetryMode   string
	Endpoint    string
}

const imdsEndpoint = "http://169.254.169.254"

// loadAWSConfig resolves the AWS configuration from the environment and shared files
func loadAWSConfig(maxAttempts int, retryMode string) (*awsConfig, error) {
	cfg := &awsConfig{MaxAttempts: maxAttempts, RetryMode: retryMode}
	if maxAttempts <= 0 {
		cfg.MaxAttempts = 3
	}
	profile := os.Getenv("AWS_PROFILE")
	if profile == "" {
		profile = "default"
	}
	shared := readSharedConfig(profile, os.Getenv("AWS_CONFIG_FILE"), os.Getenv("AWS_SHARED_CREDENTIALS_FILE"))

	cfg.Endpoint = os.Getenv("AWS_ENDPOINT_URL")
	if cfg.Region == "" {
		cfg.Region = os.Getenv("AWS_REGION")
	}
	if cfg.Region == "" {
		cfg.Region = os.Getenv("AWS_DEFAULT_REGION")
	}
	if cfg.Region == "" {
		cfg.Region = shared.region
	}
	cfg.Creds = resolveCredentials(shared)
	return cfg, nil
}

// sharedProfile holds values from the aws shared configuration files
type sharedProfile struct {
	region     string
	accessKey  string
	secretKey  string
	sessionTok string
}

func sharedConfigPath() string {
	if p := os.Getenv("AWS_CONFIG_FILE"); p != "" {
		return p
	}
	return filepath.Join(homeDir(), ".aws", "config")
}

func sharedCredentialsPath() string {
	if p := os.Getenv("AWS_SHARED_CREDENTIALS_FILE"); p != "" {
		return p
	}
	return filepath.Join(homeDir(), ".aws", "credentials")
}

func homeDir() string {
	if h := os.Getenv("HOME"); h != "" {
		return h
	}
	return ""
}

// readSharedConfig reads the profile from the shared config and credentials files
func readSharedConfig(profile, configFile, credentialsFile string) *sharedProfile {
	p := &sharedProfile{}
	configPath := configFile
	if configPath == "" {
		configPath = sharedConfigPath()
	}
	if profile != "default" {
		// a named profile must exist in the shared config file
		if _, ok := parseIni(configPath)["profile "+profile]; !ok {
			if _, ok := parseIni(configPath)[profile]; !ok {
				return p
			}
		}
	}
	// presence of a named profile is validated by the caller through the
	// shared config loader error
	if profile != "default" {
		if _, err := os.Stat(configPath); err == nil {
			sections := parseIni(configPath)
			if _, ok := sections["profile "+profile]; !ok {
				if _, ok := sections[profile]; !ok {
					return p
				}
			}
		}
	}
	credsPath := credentialsFile
	if credsPath == "" {
		credsPath = sharedCredentialsPath()
	}
	if section, ok := parseIni(credsPath)[profile]; ok {
		p.accessKey = section["aws_access_key_id"]
		p.secretKey = section["aws_secret_access_key"]
		p.sessionTok = section["aws_session_token"]
	}
	// the config file may also hold credentials
	if section, ok := parseIni(configPath)["profile "+profile]; ok {
		if p.accessKey == "" {
			p.accessKey = section["aws_access_key_id"]
		}
		if p.secretKey == "" {
			p.secretKey = section["aws_secret_access_key"]
		}
		if p.sessionTok == "" {
			p.sessionTok = section["aws_session_token"]
		}
		if p.region == "" {
			p.region = section["region"]
		}
	}
	if section, ok := parseIni(configPath)[profile]; ok {
		if p.region == "" {
			p.region = section["region"]
		}
	}
	return p
}

// parseIni parses an ini file into sections
func parseIni(path string) map[string]map[string]string {
	out := map[string]map[string]string{}
	data, err := os.ReadFile(path)
	if err != nil {
		return out
	}
	current := ""
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			current = strings.TrimSpace(line[1 : len(line)-1])
			if _, ok := out[current]; !ok {
				out[current] = map[string]string{}
			}
			continue
		}
		idx := strings.Index(line, "=")
		if idx < 0 || current == "" {
			continue
		}
		k := strings.TrimSpace(line[:idx])
		v := strings.TrimSpace(line[idx+1:])
		out[current][k] = v
	}
	return out
}

