// readSharedConfig reads the profile from the shared config and credentials files
func readSharedConfig(profile, configFile, credentialsFile string) *sharedProfile {
	p := &sharedProfile{}
	configPath := configFile
	if configPath == "" {
		configPath = sharedConfigPath()
	}
	if profile != "default" {
		// a named profile must exist in the shared config file
		if _, ok := parseIni(configPath)["profile "+profile]; !ok {
			if _, ok := parseIni(configPath)[profile]; !ok {
				return p
			}
		}
	}
	// presence of a named profile is validated by the caller through the
	// shared config loader error
	if profile != "default" {
		if _, err := os.Stat(configPath); err == nil {
			sections := parseIni(configPath)
			if _, ok := sections["profile "+profile]; !ok {
				if _, ok := sections[profile]; !ok {
					return p
				}
			}
		}
	}
	credsPath := credentialsFile
	if credsPath == "" {
		credsPath = sharedCredentialsPath()
	}
	if section, ok := parseIni(credsPath)[profile]; ok {
		p.accessKey = section["aws_access_key_id"]
		p.secretKey = section["aws_secret_access_key"]
		p.sessionTok = section["aws_session_token"]
	}
	// the config file may also hold credentials
	if section, ok := parseIni(configPath)["profile "+profile]; ok {
		if p.accessKey == "" {
			p.accessKey = section["aws_access_key_id"]
		}
		if p.secretKey == "" {
			p.secretKey = section["aws_secret_access_key"]
		}
		if p.sessionTok == "" {
			p.sessionTok = section["aws_session_token"]
		}
		if p.region == "" {
			p.region = section["region"]
		}
	}
	if section, ok := parseIni(configPath)[profile]; ok {
		if p.region == "" {
			p.region = section["region"]
		}
	}
	return p
}

// parseIni parses an ini file into sections
func parseIni(path string) map[string]map[string]string {
	out := map[string]map[string]string{}
	data, err := os.ReadFile(path)
	if err != nil {
		return out
	}
	current := ""
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, ";") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			current = strings.TrimSpace(line[1 : len(line)-1])
			if _, ok := out[current]; !ok {
				out[current] = map[string]string{}
			}
			continue
		}
		idx := strings.Index(line, "=")
		if idx < 0 || current == "" {
			continue
		}
		k := strings.TrimSpace(line[:idx])
		v := strings.TrimSpace(line[idx+1:])
		out[current][k] = v
	}
	return out
}

// resolveCredentials resolves credentials from the environment and shared files
func resolveCredentials(shared *sharedProfile) *awsCredentials {
	if id, secret := os.Getenv("AWS_ACCESS_KEY_ID"), os.Getenv("AWS_SECRET_ACCESS_KEY"); id != "" && secret != "" {
		return &awsCredentials{AccessKeyID: id, SecretAccessKey: secret, SessionToken: os.Getenv("AWS_SESSION_TOKEN")}
	}
	if shared.accessKey != "" && shared.secretKey != "" {
		return &awsCredentials{AccessKeyID: shared.accessKey, SecretAccessKey: shared.secretKey, SessionToken: shared.sessionTok}
	}
	return nil
}

// imdsCredentials fetches credentials from the instance metadata service
func imdsCredentials() (*awsCredentials, error) {
	client := &http.Client{Timeout: 1 * time.Second}
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		if attempt > 0 {
			time.Sleep(imdsDelay(attempt))
		}
		req, err := http.NewRequest(http.MethodGet, imdsEndpoint+"/latest/meta-data/iam/security-credentials/", nil)
		if err != nil {
			lastErr = err
			continue
		}
		resp, err := client.Do(req)
		if err != nil {
			lastErr = fmt.Errorf("request send failed, %s", err)
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode != 200 {
			lastErr = fmt.Errorf("https response error StatusCode: %d, api error: %s", resp.StatusCode, strings.TrimSpace(string(body)))
			continue
		}
		role := strings.TrimSpace(string(body))
		if role == "" {
			lastErr = errors.New("no EC2 IMDS role found")
			continue
		}
		resp2, err := client.Get(imdsEndpoint + "/latest/meta-data/iam/security-credentials/" + role)
		if err != nil {
			lastErr = fmt.Errorf("request send failed, %s", err)
			continue
		}
		body2, _ := io.ReadAll(resp2.Body)
		resp2.Body.Close()
		var data struct {
			AccessKeyID     string `json:"AccessKeyId"`
			SecretAccessKey string `json:"SecretAccessKey"`
			Token           string `json:"Token"`
		}
		if err := json.Unmarshal(body2, &data); err != nil {
			lastErr = err
			continue
		}
		return &awsCredentials{AccessKeyID: data.AccessKeyID, SecretAccessKey: data.SecretAccessKey, SessionToken: data.Token}, nil
	}
	if lastErr == nil {
		lastErr = errors.New("no EC2 IMDS role found")
	}
	return nil, fmt.Errorf("get identity: get credentials: failed to refresh cached credentials, no EC2 IMDS role found, operation error ec2imds: GetMetadata, exceeded maximum number of attempts, 3, %s", lastErr)
}

func imdsDelay(attempt int) time.Duration {
	d := time.Duration(1<<attempt) * time.Second
	if d > 20*time.Second {
		d = 20 * time.Second
	}
	return time.Duration(rand.Int63n(int64(d)))
}

// retryDelay returns the delay before the given retry (1-based)
func retryDelay(retry int) time.Duration {
	delay := time.Duration(1<<retry) * time.Second
	if delay > 20*time.Second {
		delay = 20 * time.Second
	}
	if delay >= 20*time.Second {
		return delay
	}
	return time.Duration(rand.Int63n(int64(delay)))
}

// signRequest adds AWS SigV4 authorization headers to the request
func signRequest(req *http.Request, body []byte, creds *awsCredentials, region, service string) {
	now := time.Now().UTC()
	amzDate := now.Format("20060102T150405Z")
	dateStamp := now.Format("20060102")
	req.Header.Set("X-Amz-Date", amzDate)

	payloadHash := sha256.Sum256(body)
	payloadHex := hex.EncodeToString(payloadHash[:])

	canonicalURI := req.URL.Path
	if canonicalURI == "" {
		canonicalURI = "/"
	}
	host := req.URL.Host
	req.Header.Set("Host", host)

	canonicalQuery := canonicalQueryString(req)

	headers := map[string]string{
		"content-type": req.Header.Get("Content-Type"),
		"host":         host,
		"x-amz-date":   amzDate,
	}
	if req.Header.Get("X-Amz-Target") != "" {
		headers["x-amz-target"] = req.Header.Get("X-Amz-Target")
	}
	if creds.SessionToken != "" {
		req.Header.Set("X-Amz-Security-Token", creds.SessionToken)
		headers["x-amz-security-token"] = creds.SessionToken
	}
	for k, v := range extraSignedHeaders(req) {
		headers[k] = v
	}
	names := make([]string, 0, len(headers))
	for k := range headers {
		names = append(names, k)
	}
	sort.Strings(names)
	canonicalHeaders := ""
	for _, n := range names {
		canonicalHeaders += n + ":" + strings.TrimSpace(headers[n]) + "\n"
	}
	signedHeaders := strings.Join(names, ";")

	canonicalRequest := strings.Join([]string{
		req.Method,
		canonicalURI,
		canonicalQuery,
		canonicalHeaders,
		signedHeaders,
		payloadHex,
	}, "\n")

	scope := strings.Join([]string{dateStamp, region, service, "aws4_request"}, "/")
	h1 := hmac.New(sha256.New, []byte("AWS4"+creds.SecretAccessKey))
	h1.Write([]byte(dateStamp))
	kDate := h1.Sum(nil)
	h2 := hmac.New(sha256.New, kDate)
	h2.Write([]byte(region))
	kRegion := h2.Sum(nil)
	h3 := hmac.New(sha256.New, kRegion)
	h3.Write([]byte(service))
	kService := h3.Sum(nil)
	h4 := hmac.New(sha256.New, kService)
	h4.Write([]byte("aws4_request"))
	kSigning := h4.Sum(nil)

	h5 := hmac.New(sha256.New, kSigning)
	h5.Write([]byte(canonicalRequest))
	signature := hex.EncodeToString(h5.Sum(nil))

	req.Header.Set("Authorization", fmt.Sprintf("AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s",
		creds.AccessKeyID, scope, signedHeaders, signature))
}

// extraSignedHeaders returns additional headers that should be signed
func extraSignedHeaders(req *http.Request) map[string]string {
	out := map[string]string{}
	for k, v := range req.Header {
		lk := strings.ToLower(k)
		switch lk {
		case "amz-sdk-invocation-id", "amz-sdk-request", "content-length", "x-amz-content-sha256":
			out[lk] = v[0]
		}
	}
	return out
}

func canonicalQueryString(req *http.Request) string {
	if req.URL.RawQuery == "" {
		return ""
	}
	values, err := url.ParseQuery(req.URL.RawQuery)
	if err != nil {
		return req.URL.RawQuery
	}
	keys := make([]string, 0, len(values))
	for k := range values {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	parts := []string{}
	for _, k := range keys {
		vals := values[k]
		sort.Strings(vals)
		for _, v := range vals {
			parts = append(parts, uriEncode(k)+"="+uriEncode(v))
		}
	}
	return strings.Join(parts, "&")
}

func uriEncode(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~' {
			sb.WriteByte(c)
		} else {
			fmt.Fprintf(&sb, "%%%02X", c)
		}
	}
	return sb.String()
}

// awsRequest performs a signed request with retries, returning the response body
func awsRequest(cfg *awsConfig, service, operation string, req *http.Request, body []byte) ([]byte, *http.Response, error) {
	if cfg.Creds == nil {
		_, err := imdsCredentials()
		if err != nil {
			return nil, nil, fmt.Errorf("operation error %s: %s, exceeded maximum number of attempts, %d, %s",
				service, operation, cfg.MaxAttempts, err)
		}
	}
	var lastErr error
	for attempt := 1; attempt <= cfg.MaxAttempts; attempt++ {
		if attempt > 1 {
			time.Sleep(retryDelay(attempt - 1))
		}
		if cfg.Region == "" {
			return nil, nil, fmt.Errorf("operation error %s: %s, failed to resolve service endpoint, endpoint rule error, Invalid Configuration: Missing Region", service, operation)
		}
		creds := cfg.Creds
		if creds == nil {
			creds = &awsCredentials{}
		}
		clone := req.Clone(req.Context)
		if clone.Body != nil && body != nil {
			clone.Body = io.NopCloser(bytes.NewReader(body))
		}
		clone.Header.Set("Amz-Sdk-Invocation-Id", invocationID())
		clone.Header.Set("Amz-Sdk-Request", fmt.Sprintf("attempt=%d; max=%d", attempt, cfg.MaxAttempts))
		signRequest(clone, body, creds, cfg.Region, service)
		resp, err := http.DefaultClient.Do(clone)
		if err != nil {
			lastErr = fmt.Errorf("https response error StatusCode: 0, RequestID: %s, request send failed, %s", requestIDSuffix(service), err)
			continue
		}
		respBody, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode >= 400 {
			apiErr := parseAPIError(respBody)
			lastErr = fmt.Errorf("https response error StatusCode: %d, RequestID: %s, %s", resp.StatusCode, resp.Header.Get("X-Amzn-Requestid"), apiErr)
			if resp.StatusCode >= 500 {
				continue
			}
			return nil, resp, fmt.Errorf("operation error %s: %s, %s", service, operation, lastErr)
		}
		if err := validateResponse(service, operation, respBody); err != nil {
			lastErr = fmt.Errorf("https response error StatusCode: %d, RequestID: %s, deserialization failed, failed to decode response body, %s", resp.StatusCode, resp.Header.Get("X-Amzn-Requestid"), err)
			continue
		}
		return respBody, resp, nil
	}
	if lastErr == nil {
		lastErr = errors.New("unknown error")
	}
	return nil, nil, fmt.Errorf("operation error %s: %s, exceeded maximum number of attempts, %d, %s", service, operation, cfg.MaxAttempts, lastErr)
}

var invocationCounter = 0

func invocationID() string {
	invocationCounter++
	return fmt.Sprintf("chamber-%d", invocationCounter)
}

func requestIDSuffix(service string) string {
	return ""
}

// parseAPIError extracts the error code and message from an error response
func parseAPIError(body []byte) string {
	var data map[string]interface{}
	if err := json.Unmarshal(body, &data); err != nil {
		return strings.TrimSpace(string(body))
	}
	code, _ := data["__type"].(string)
	msg, _ := data["message"].(string)
	if msg == "" {
		msg, _ = data["Message"].(string)
	}
	if code == "" {
		if idx := strings.Index(msg, ":"); idx > 0 {
			code = strings.TrimSpace(msg[:idx])
			msg = strings.TrimSpace(msg[idx+1:])
		}
	}
	if code == "" {
		return msg
	}
	if msg == "" {
		return code
	}
	return fmt.Sprintf("api error %s: %s", code, msg)
}

// validateResponse performs minimal deserialization validation
func validateResponse(service, operation string, body []byte) error {
	if len(bytes.TrimSpace(body)) == 0 {
		return nil
	}
	var data map[string]interface{}
	if err := json.Unmarshal(body, &data); err != nil {
		return err
	}
	// GetParameters: InvalidParameters must be a list of strings
	if v, ok := data["InvalidParameters"]; ok {
		items, ok := v.([]interface{})
		if !ok {
			return errors.New("expected PSInvalidParameters to be of type list, got map[string]interface {} instead")
		}
		for _, item := range items {
			if _, ok := item.(string); !ok {
				return errors.New("expected PSParameterName to be of type string, got map[string]interface {} instead")
			}
		}
	}
	return nil
}

