		input := describeParametersInput{
			MaxResults: 50,
			ParameterFilters: []ssmParameterFilter{{
				Key:    "Name",
				Option: "BeginsWith",
				Values: []string{"/"},
			}},
		}
		if nextToken != "" {
			input.NextToken = nextToken
		}
		var res describeParametersOutput
		if err := s.ssmPost("DescribeParameters", input, &res); err != nil {
			return nil, err
		}
		for _, p := range res.Parameters {
			name := strings.TrimPrefix(p.Name, "/")
			parts := strings.Split(name, "/")
			key := parts[len(parts)-1]
			out = append(out, types.Parameter{
				Service:  strings.Join(parts[:len(parts)-1], "/"),
				Key:      key,
				Modified: epochToTime(p.LastModifiedDate),
				User:     p.LastModifiedUser,
			})
		}
		if res.NextToken == "" {
			break
		}
		nextToken = res.NextToken
	}
	return out, nil
}

func serviceOfName(name string) string {
	name = strings.TrimPrefix(name, "/")
	parts := strings.Split(name, "/")
	return strings.Join(parts[:len(parts)-1], "/")
}

// getParameter reads a single parameter including its metadata
func (s *ssmStore) getParameter(name string) (*types.Parameter, error) {
	var res struct {
		Parameters        []ssmParameter `json:"Parameters"`
		InvalidParameters []string       `json:"InvalidParameters"`
	}
	if err := s.ssmPost("GetParameters", map[string]interface{}{
		"Names":          []string{name},
		"WithDecryption": true,
	}, &res); err != nil {
		return nil, err
	}
	if len(res.Parameters) == 0 {
		return nil, ErrParameterNotFound
	}
	p := res.Parameters[0]
	// fetch the metadata for the parameter
	service := serviceOfName(p.Name)
	metadata, err := s.describeParametersByPath(service)
	if err != nil {
		return nil, err
	}
	parameter := &types.Parameter{
		Key:      keyFromName(p.Name, service),
		Service:  service,
		Value:    p.Value,
		Version:  0,
		Modified: epochToTime(p.LastModifiedDate),
		User:     p.LastModifiedUser,
	}
	for _, m := range metadata {
		if m.Key == parameter.Key {
			parameter.Modified = m.Modified
			parameter.User = m.User
			break
		}
	}
	return parameter, nil
}

func (s *ssmStore) getParameters(names []string) ([]types.Parameter, error) {
	var res struct {
		Parameters        []ssmParameter `json:"Parameters"`
		InvalidParameters []string       `json:"InvalidParameters"`
	}
	if err := s.ssmPost("GetParameters", map[string]interface{}{
		"Names":          names,
		"WithDecryption": true,
	}, &res); err != nil {
		return nil, err
	}
	out := make([]types.Parameter, 0, len(res.Parameters))
	for _, p := range res.Parameters {
		out = append(out, types.Parameter{Key: p.Name, Value: p.Value})
	}
	return out, nil
}

// Get reads secrets from the store
func (s *ssmStore) Get(parameters ...types.ParameterRequest) ([]types.ParameterVersion, error) {
	out := make([]types.ParameterVersion, 0, len(parameters))
	for _, parameter := range parameters {
		if parameter.Version != -1 {
			v, err := s.getParameterVersion(parameter)
			if err != nil {
				return nil, err
			}
			out = append(out, *v)
			continue
		}
		p, err := s.getParameter(parameterName(parameter.Service, parameter.Key))
		if err != nil {
			return nil, err
		}
		out = append(out, types.ParameterVersion{
			Key:      p.Key,
			Value:    p.Value,
			Version:  p.Version,
			Modified: p.Modified,
			User:     p.User,
		})
	}
	return out, nil
}

// getParameterVersion reads a specific version of a parameter
func (s *ssmStore) getParameterVersion(parameter types.ParameterRequest) (*types.ParameterVersion, error) {
	history, err := s.GetHistory(types.ParameterRequest{Service: parameter.Service, Key: parameter.Key, Version: -1})
	if err != nil {
		return nil, ErrParameterNotFound
	}
	for _, v := range history {
		if v.Version == parameter.Version {
			return &types.ParameterVersion{
				Key:      v.Key,
				Value:    v.Value,
				Version:  v.Version,
				Modified: v.Modified,
				User:     v.User,
