	NextToken  string             `json:"NextToken"`
}

// GetHistory reads the history of a parameter
func (s *ssmStore) GetHistory(parameters ...types.ParameterRequest) ([]types.ParameterVersionHistory, error) {
	out := make([]types.ParameterVersionHistory, 0)
	for _, parameter := range parameters {
		name := parameterName(parameter.Service, parameter.Key)
		nextToken := ""
		for {
			payload := map[string]interface{}{
				"Name":           name,
				"WithDecryption": false,
			}
			if nextToken != "" {
				payload["NextToken"] = nextToken
			}
			var res getParameterHistoryOutput
			if err := s.ssmPost("GetParameterHistory", payload, &res); err != nil {
				return nil, err
			}
			for _, p := range res.Parameters {
				out = append(out, types.ParameterVersionHistory{
					Key:      parameter.Key,
					Value:    p.Value,
					Version:  0,
					Modified: epochToTime(p.LastModifiedDate),
					User:     p.LastModifiedUser,
				})
			}
			if res.NextToken == "" {
				break
			}
			nextToken = res.NextToken
		}
	}
	return out, nil
}

// Write writes secrets to the store
func (s *ssmStore) Write(parameters ...types.Parameter) error {
	for _, parameter := range parameters {
		name := parameterName(parameter.Service, parameter.Key)
		if _, err := s.getParameter(name); err != nil && err != ErrParameterNotFound {
			return err
		}
		config, err := s.readStoreConfig()
		if err != nil {
			return err
		}
		_ = config
		if err := s.ssmPost("PutParameter", map[string]interface{}{
			"Description": "1",
			"KeyId":       s.kmsKeyAlias(),
			"Name":        name,
			"Overwrite":   true,
			"Type":        "SecureString",
			"Value":       parameter.Value,
		}, nil); err != nil {
			return err
		}
	}
	return nil
}

// WriteWithTags writes a secret and sets its tags
func (s *ssmStore) WriteWithTags(parameter types.Parameter, tags []types.Tag) error {
	if err := s.Write(parameter); err != nil {
		return err
	}
	name := parameterName(parameter.Service, parameter.Key)
	if err := s.ssmPost("AddTagsToResource", map[string]interface{}{
		"ResourceId":   name,
		"ResourceType": "Parameter",
		"Tags":         tagsToSSM(tags),
	}, nil); err != nil {
		return err
	}
	return nil
}

// WriteTags writes tags for a parameter
func (s *ssmStore) WriteTags(key types.ParameterRequest, tags []types.Tag, deleteOthers bool) error {
	if err := s.readStoreConfig(); err != nil {
		return err
	}
	if deleteOthers {
		existing, err := s.ReadTags(key)
		if err != nil {
			return err
		}
		_ = existing
	}
	name := parameterName(key.Service, key.Key)
	if err := s.ssmPost("AddTagsToResource", map[string]interface{}{
		"ResourceId":   name,
		"ResourceType": "Parameter",
		"Tags":         tagsToSSM(tags),
	}, nil); err != nil {
		return err
	}
	return nil
}

// ReadTags reads the tags of a parameter
func (s *ssmStore) ReadTags(key types.ParameterRequest) ([]types.Tag, error) {
	var res struct {
		TagList []types.Tag `json:"TagList"`
	}
	name := parameterName(key.Service, key.Key)
	if err := s.ssmPost("ListTagsForResource", map[string]interface{}{
		"ResourceId":   name,
		"ResourceType": "Parameter",
	}, &res); err != nil {
		return nil, err
	}
	return res.TagList, nil
}

// DeleteTags deletes tags from a parameter
func (s *ssmStore) DeleteTags(key types.ParameterRequest, tags []types.Tag) error {
	if err := s.readStoreConfig(); err != nil {
		return err
	}
	keys := make([]string, 0, len(tags))
	for _, tag := range tags {
		keys = append(keys, tag.Key)
	}
	name := parameterName(key.Service, key.Key)
	if err := s.ssmPost("RemoveTagsFromResource", map[string]interface{}{
		"ResourceId":   name,
		"ResourceType": "Parameter",
		"TagKeys":      keys,
	}, nil); err != nil {
		return err
	}
	return nil
}

// Delete deletes secrets from the store
func (s *ssmStore) Delete(parameters ...types.ParameterRequest) error {
	for _, parameter := range parameters {
		name := parameterName(parameter.Service, parameter.Key)
		if _, err := s.getParameter(name); err != nil {
			return err
		}
		if err := s.ssmPost("DeleteParameter", map[string]interface{}{
			"Name": name,
		}, nil); err != nil {
			return err
		}
	}
	return nil
}

// readStoreConfig reads the store configuration parameter
func (s *ssmStore) readStoreConfig() (string, error) {
	var res struct {
		Parameters        []ssmParameter `json:"Parameters"`
		InvalidParameters []string       `json:"InvalidParameters"`
	}
	if err := s.ssmPost("GetParameters", map[string]interface{}{
		"Names":          []string{"/_chamber/store-config"},
		"WithDecryption": true,
	}, &res); err != nil {
		return "", err
	}
	if len(res.Parameters) == 0 {
		return "", nil
	}
	// fetch the metadata of the store config
	if _, err := s.describeParametersByPath("_chamber"); err != nil {
		return "", err
	}
	return res.Parameters[0].Value, nil
}

func (s *ssmStore) kmsKeyAlias() string {
	if alias := envChamberKMSKeyAlias(); alias != "" {
		return alias
	}
	return "alias/parameter_store_key"
}

func tagsToSSM(tags []types.Tag) []types.Tag {
	return tags
}
