// ssmStore implements the SSM Parameter Store backend
type ssmStore struct {
	cfg *awsConfig
}

// NewSSMStore creates an SSM Parameter Store backend
func NewSSMStore(retries int, retryMode string) (Backend, error) {
	cfg, err := loadAWSConfigWithProfile(retries, retryMode)
	if err != nil {
		return nil, err
	}
	return &ssmStore{cfg: cfg}, nil
}

// parameterName builds the parameter name for a service and key
func parameterName(service, key string) string {
	return fmt.Sprintf("/%s/%s", strings.ToLower(service), strings.ToLower(key))
}

// servicePath builds the path for a service
func servicePath(service string) string {
	return fmt.Sprintf("/%s", strings.ToLower(service))
}

// ssmPost performs an SSM API call
func (s *ssmStore) ssmPost(operation string, payload interface{}, result interface{}) error {
	body, err := json.Marshal(payload)
	if err != nil {
		return err
	}
	endpoint := s.endpoint()
	req, err := http.NewRequest(http.MethodPost, endpoint, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Content-Type", "application/x-amz-json-1.1")
	req.Header.Set("X-Amz-Target", ssmOperationPrefix+operation)
	respBody, _, err := awsRequest(s.cfg, "SSM", operation, req, body)
	if err != nil {
		return err
	}
	if result == nil {
		return nil
	}
	return json.Unmarshal(respBody, result)
}

func (s *ssmStore) endpoint() string {
	if e := osEndpointSSM(); e != "" {
		return e
	}
	if s.cfg.Endpoint != "" {
		return s.cfg.Endpoint
	}
	return fmt.Sprintf("https://ssm.%s.amazonaws.com/", s.cfg.Region)
}

