func (s *ssmStore) listParameters(paths []string, withValues bool) ([]types.Parameter, error) {
	result := make([]types.Parameter, 0, 10)
	for _, path := range paths {
		if withValues {
			params, err := s.getParametersByPath(path)
			if err != nil {
				return nil, err
			}
			result = append(result, params...)
			continue
		}
		params, err := s.describeParametersByPath(path)
		if err != nil {
			return nil, err
		}
		result = append(result, params...)
	}
	return result, nil
}

func (s *ssmStore) describeParametersByPath(path string) ([]types.Parameter, error) {
	var out []types.Parameter
	nextToken := ""
	for {
		input := describeParametersInput{
			ParameterFilters: []ssmParameterFilter{{
				Key:    "Path",
				Option: "OneLevel",
				Values: []string{servicePath(path)},
			}},
		}
		if nextToken != "" {
			input.NextToken = nextToken
		}
		var res describeParametersOutput
		if err := s.ssmPost("DescribeParameters", input, &res); err != nil {
			return nil, err
		}
		for _, p := range res.Parameters {
			if p.LastModifiedDate == 0 {
				// chamber panics when the last modified date is missing
				panic("runtime error: invalid memory address or nil pointer dereference")
			}
			out = append(out, types.Parameter{
				Key:      keyFromName(p.Name, path),
				Version:  0,
				Modified: epochToTime(p.LastModifiedDate),
				User:     p.LastModifiedUser,
			})
		}
		if res.NextToken == "" {
			break
		}
		nextToken = res.NextToken
	}
