// keyFromName extracts the key from a parameter name
func keyFromName(name, service string) string {
	prefix := fmt.Sprintf("/%s/", strings.ToLower(service))
	if strings.HasPrefix(name, prefix) {
		return name[len(prefix):]
	}
	return strings.TrimPrefix(name, "/")
}

// ListServices lists the services in the store
func (s *ssmStore) ListServices(providers ...string) ([]types.Service, error) {
	prefix := "/"
	if len(providers) > 0 && providers[0] != "" {
		prefix = servicePath(providers[0])
	}
	services := map[string]struct{}{}
	nextToken := ""
	for {
		input := describeParametersInput{
			MaxResults: 50,
			ParameterFilters: []ssmParameterFilter{{
				Key:    "Name",
				Option: "BeginsWith",
				Values: []string{prefix},
			}},
		}
		if nextToken != "" {
			input.NextToken = nextToken
		}
		var res describeParametersOutput
		if err := s.ssmPost("DescribeParameters", input, &res); err != nil {
			return nil, err
		}
		for _, p := range res.Parameters {
			name := strings.TrimPrefix(p.Name, "/")
			if prefix != "/" {
				name = strings.TrimPrefix(name, strings.TrimPrefix(prefix, "/")+"/")
			}
			parts := strings.Split(name, "/")
			if parts[0] == "" {
				continue
			}
			services[parts[0]] = struct{}{}
		}
		if res.NextToken == "" {
			break
		}
		nextToken = res.NextToken
	}
	result := make([]types.Service, 0, len(services))
	for name := range services {
		result = append(result, types.Service{Name: name})
	}
	sortServices(result)
	return result, nil
}

// Find finds parameters matching a secret name across all services
func (s *ssmStore) Find(secretName string, byValue bool) ([]types.Parameter, error) {
	services, err := s.ListServices()
	if err != nil {
		return nil, err
	}
	if !byValue {
		all, err := s.listAllParameters()
		if err != nil {
			return nil, err
		}
		out := make([]types.Parameter, 0, len(all))
		for _, p := range all {
			if strings.Split(p.Key, "/")[0] == secretName {
				out = append(out, p)
			}
		}
		return out, nil
	}
	out := make([]types.Parameter, 0)
	for _, service := range services {
		params, err := s.List(service.Name)
		if err != nil {
			return nil, err
		}
		if len(params) == 0 {
			continue
		}
		names := make([]string, 0, len(params))
		for _, p := range params {
			names = append(names, parameterName(service.Name, p.Key))
		}
		values, err := s.getParameters(names)
		if err != nil {
			return nil, err
		}
		for _, v := range values {
			if v.Value == secretName {
				out = append(out, types.Parameter{Service: serviceOfName(v.Key), Key: v.Key, Value: v.Value})
			}
		}
	}
	return out, nil
}

func (s *ssmStore) listAllParameters() ([]types.Parameter, error) {
	out := make([]types.Parameter, 0)
	nextToken := ""
	for {
		input := describeParametersInput{
			MaxResults: 50,
			ParameterFilters: []ssmParameterFilter{{
				Key:    "Name",
				Option: "BeginsWith",
				Values: []string{"/"},
