{"command": "cd /workspace && cat > store/s3store.go <<'EOF'
package store

import (
	"encoding/json"
	"fmt"
	"net/http"
	"sort"
	"strconv"
	"strings"

	"chamber/types"
)

const s3Service = "s3"

// secretVersion is a version of a secret stored in an s3 object
type secretVersion struct {
	Value   string `json:"value"`
	Version int    `json:"version"`
}

// secretObject is the on-disk representation of a secret in s3
type secretObject struct {
	Key     string                   `json:"key"`
	Service string                   `json:"service"`
	Values  map[string]secretVersion `json:"values"`
}

// latest holds the latest values of all secrets in a service
type latest struct {
	Latest map[string]string `json:"latest"`
}

// s3Store implements the S3 backend
type s3Store struct {
	cfg     *awsConfig
	bucket  string
	kms     bool
	kmsKeyAlias string
}

// NewS3Store creates an S3 backend
func NewS3Store(bucket, kmsKeyAlias string, retries int, useKMS bool) (Backend, error) {
	cfg, err := loadAWSConfigWithProfile(retries, "standard")
	if err != nil {
		return nil, err
	}
	return &s3Store{cfg: cfg, bucket: bucket, kms: useKMS, kmsKeyAlias: kmsKeyAlias}, nil
}

func (s *s3Store) endpointFor(key string) string {
	if s.cfg.Endpoint != "" {
		return fmt.Sprintf("%s/%s/%s", strings.TrimSuffix(s.cfg.Endpoint, "/"), s.bucket, key)
	}
	return fmt.Sprintf("https://%s.%s/%s", s.bucket, s3Host(), key)
}

func (s *s3Store) s3Host() string {
	return fmt.Sprintf("s3.%s.amazonaws.com", s.cfg.Region)
}

// validBucketName reports whether the bucket can be used with virtual hosted style
func validBucketName(bucket string) bool {
	if len(bucket) < 3 || len(bucket) > 63 {
		return false
	}
	for i := 0; i < len(bucket); i++ {
		c := bucket[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-' || c == '.') {
			return false
		}
	}
	return true
}

// s3Get performs a GET object request
func (s *s3Store) s3Get(key string) ([]byte, error) {
	endpoint := s.objectURL(key)
	req, err := http.NewRequest(http.MethodGet, endpoint, nil)
	if err != nil {
		return nil, err
	}
	body, _, err := awsRequestS3(s.cfg, "GetObject", req)
	if err != nil {
		return nil, err
	}
	return body, nil
}

// s3Put performs a PUT object request
func (s *s3Store) s3Put(key string, body []byte) error {
	req, err := http.NewRequest(http.MethodPut, s.objectURL(key), nil)
	if err != nil {
		return err
	}
	_, _, err = awsRequestS3(s.cfg, "PutObject", req, body)
	return err
}

// s3Delete performs a DELETE object request
func (s *s3Store) s3Delete(key string) error {
	req, err := http.NewRequest(http.MethodDelete, s.objectURL(key), nil)
	if err != nil {
		return err
	}
	_, _, err = awsRequestS3(s.cfg, "DeleteObject", req)
	return err
}

func (s *s3Store) objectURL(key string) string {
	if s.cfg.Endpoint != "" {
		return fmt.Sprintf("%s/%s/%s", strings.TrimSuffix(s.cfg.Endpoint, "/"), s.bucket, key)
	}
	if validBucketName(s.bucket) {
		return fmt.Sprintf("https://%s.s3.%s.amazonaws.com/%s?x-id=GetObject", s.bucket, s.cfg.Region, key)
	}
	return fmt.Sprintf("https://s3.%s.amazonaws.com/%s/%s?x-id=GetObject", s.cfg.Region, s.bucket, key)
}

// awsRequestS3 performs a signed S3 request with retries
func awsRequestS3(cfg *awsConfig, operation string, req *http.Request, body ...[]byte) ([]byte, *http.Response, error) {
	var payload []byte
	if len(body) > 0 {
		payload = body[0]
	}
	return awsRequestWithHost(cfg, "S3", operation, req, payload, true)
}

// List lists the secrets of a service
func (s *s3Store) List(paths ...string) ([]types.Parameter, error) {
	out := make([]types.Parameter, 0)
	for _, path := range paths {
		params, err := s.listService(path)
		if err != nil {
			return nil, err
		}
		out = append(out, params...)
	}
	return out, nil
}

// ListWithValues lists the secrets of a service including values
func (s *s3Store) ListWithValues(paths ...string) ([]types.Parameter, error) {
	out := make([]types.Parameter, 0)
	for _, path := range paths {
		params, err := s.listServiceWithValues(path)
		if err != nil {
			return nil, err
		}
		out = append(out, params...)
	}
	return out, nil
}

func (s *s3Store) listService(service string) ([]types.Parameter, error) {
	latest, err := s.readLatest(service)
	if err != nil {
		return nil, err
	}
	keys := make([]string, 0, len(latest.Latest))
	for k := range latest.Latest {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out := make([]types.Parameter, 0, len(keys))
	for _, key := range keys {
		obj, err := s.readSecret(service, key)
		if err != nil {
			return nil, err
		}
		version := 0
		for _, v := range obj.Values {
			if v.Version > version {
				version = v.Version
			}
		}
		out = append(out, types.Parameter{Key: key, Version: version})
	}
	return out, nil
}

func (s *s3Store) listServiceWithValues(service string) ([]types.Parameter, error) {
	latest, err := s.readLatest(service)
	if err != nil {
		return nil, err
	}
	keys := make([]string, 0, len(latest.Latest))
	for k := range latest.Latest {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	out := make([]types.Parameter, 0, len(keys))
	for _, key := range keys {
		out = append(out, types.Parameter{Key: key, Value: latest.Latest[key]})
	}
	return out, nil
}

// readLatest reads the __latest.json object of a service
func (s *s3Store) readLatest(service string) (*latest, error) {
	body, err := s.s3Get(fmt.Sprintf("%s/__latest.json", service))
	if err != nil {
		return nil, err
	}
	var l latest
	if err := json.Unmarshal(body, &l); err != nil {
		return nil, err
	}
	return &l, nil
}

// readSecret reads the secret object of a key
func (s *s3Store) readSecret(service, key string) (*secretObject, error) {
