	out := make([]types.ParameterVersion, 0, len(parameters))
	for _, parameter := range parameters {
		service := parameter.Service
		key := strings.ToLower(parameter.Key)
		if parameter.Version != -1 {
			obj, err := s.readSecret(service, key)
			if err != nil {
				return nil, err
			}
			found := false
			for _, v := range obj.Values {
				if v.Version == parameter.Version {
					out = append(out, types.ParameterVersion{Key: key, Value: v.Value, Version: v.Version})
					found = true
					break
				}
			}
			if !found {
