func (s *source) snippet(pos Position, caretLine int) string {
	n := len(s.lines)
	start := pos.Line - 3
	if start < 1 {
		start = 1
	}
	end := pos.Line + 3
	if end > n {
		end = n
	}
	if caretLine-1 > end {
		end = caretLine - 1
		if end > n {
			end = n
		}
	}
	w := s.width(start, end)
	numFmt := fmt.Sprintf("%%%dd | ", w)

	var sb strings.Builder
	for i := start; i < pos.Line; i++ {
		sb.WriteString("  ")
		sb.WriteString(fmt.Sprintf(numFmt, i))
		sb.WriteString(strings.TrimRight(s.line(i), " \\t"))
		sb.WriteString("\\n")
	}
	sb.WriteString("> ")
	sb.WriteString(fmt.Sprintf(numFmt, pos.Line))
	sb.WriteString(strings.TrimRight(s.line(pos.Line), " \\t"))
	sb.WriteString("\\n")
	// lines between the error line and the caret line
	for i := pos.Line + 1; i <= caretLine-1 && i <= end; i++ {
		sb.WriteString("  ")
		sb.WriteString(fmt.Sprintf(numFmt, i))
		sb.WriteString(strings.TrimRight(s.line(i), " \\t"))
		sb.WriteString("\\n")
	}
	sb.WriteString(strings.Repeat(" ", 2+w+3+pos.Col-1))
	sb.WriteString("^")
	for i := caretLine; i <= end; i++ {
		sb.WriteString("\\n")
		sb.WriteString("  ")
		sb.WriteString(fmt.Sprintf(numFmt, i))
		sb.WriteString(strings.TrimRight(s.line(i), " \\t"))
	}
	// trailing line, rendered empty, when the document continues past the window
	if end < n {
		sb.WriteString("\\n")
		sb.WriteString("  ")
		sb.WriteString(fmt.Sprintf(numFmt, end+1))
	}
	return sb.String()
}
'''
